import sys, collections; sys.path.insert(0,'/tmp/py')
from png import decode
w,h,ct,bd,px=decode('A_full.png')
xs=[];ys=[]
for i,p in enumerate(px):
    if p==(255,255,255,255): xs.append(i%w); ys.append(i//w)
print('white bbox',min(xs),max(xs),min(ys),max(ys))
