row0=[px[x] for x in range(w)]
print('row0 first colors', row0[:6], row0[-6:])
# gradient: horizontal interpolation between (107,203,165) at x=0 and (202,244,194) at x=w-1
def expected(x):
    t=x/(w-1)
    return (round(107+(202-107)*t), round(203+(244-203)*t), round(165+(194-165)*t),255)
bad=[]
for i,p in enumerate(px):
    x=i%w;y=i//w
    e=expected(x)
    if p!=e: bad.append((x,y,p))
print('bad count',len(bad))
if bad:
    xs2=[b[0] for b in bad]; ys2=[b[1] for b in bad]
    print('bad bbox',min(xs2),max(xs2),min(ys2),max(ys2))
    print(bad[:20])
EOF"}

