{"command": "cd /tmp/t && cat <<'EOF' > /tmp/py/mkpng.py
import zlib,struct,sys
def mk(w,h,path):
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    ihdr=struct.pack('>IIBBBBB',w,h,8,6,0,0,0)
    raw=b''
    for y in range(h): raw+=b'\x00'+bytes([ (x*7)%256 for x in range(w*4)])
    open(path,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',ihdr)+chunk(b'IDAT',zlib.compress(raw,6))+chunk(b'IEND',b''))
for (a,b) in [(10,10),(20,30),(100,50),(300,200),(1000,800)]:
    mk(a,b,'sz_%dx%d.png'%(a,b))
EOF
