import sys, collections
sys.path.insert(0,'/tmp/py')
from png import decode
def load(p): 
    w,h,ct,bd,px=decode(p); return w,h,px
def bbox(px,w,color):
    xs=[];ys=[]
    for i,p in enumerate(px):
        if p[:3]==color and p[3]==255: xs.append(i%w); ys.append(i//w)
    if not xs: return None
    return (min(xs),max(xs),min(ys),max(ys),len(xs))
def profile_rows(px,w,h,colors,y0=0,y1=None,x0=0,x1=None):
    y1=y1 or h; x1=x1 or w
    out=[]
    for y in range(y0,y1):
        n=0; cols=collections.Counter()
        for x in range(x0,x1):
            c=px[y*w+x]
            if c[:3] in colors: n+=1; cols[c[:3]]+=1
