//! Hex color parsing.
//!
//! The original implementation parses `#RRGGBB` and `#RRGGBBAA` strings and
//! panics with the message `Invalid hex color: <input>` when the input does not
//! have the expected shape.
use serde::Deserialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Color {
    pub fn new(r: u8, g: u8, b: u8, a: u8) -> Self {
        Color { r, g, b, a }
    }

    /// Create a color from a `#RRGGBB` or `#RRGGBBAA` hex string.
    pub fn from_hex(hex: &str) -> Self {
        let digits = hex.strip_prefix('#').unwrap_or_else(|| {
            panic!("Invalid hex color: {}", hex)
        });

        match digits.len() {
            6 | 8 => {}
            _ => {
                panic!("Invalid hex color: {}", hex)
            }
        }

        let r = u8::from_str_radix(&digits[0..2], 16).unwrap();
        let g = u8::from_str_radix(&digits[2..4], 16).unwrap();
        let b = u8::from_str_radix(&digits[4..6], 16).unwrap();
        let a = if digits.len() == 8 {
            u8::from_str_radix(&digits[6..8], 16).unwrap()
        } else {
            255
        };
        Color { r, g, b, a }
    }

    pub fn blend_over(&self, bg: (u8, u8, u8, u8)) -> (u8, u8, u8, u8) {
        let a = self.a as u32;
        let ia = 255 - a;
        let mix = |fg: u8, b: u8| -> u8 {
            ((fg as u32 * a + b as u32 * ia) / 255) as u8
        };
        (mix(self.r, bg.0), mix(self.g, bg.1), mix(self.b, bg.2), 255)
    }

    pub fn to_rgba(self) -> (u8, u8, u8, u8) {
        (self.r, self.g, self.b, self.a)
    }
}

#[derive(Deserialize)]
#[serde(untagged)]
enum _Unused {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_short() {
        let c = Color::from_hex("#ff00ff");
        assert_eq!(c, Color::new(255, 0, 255, 255));
    }
}
EOF
