import sys,subprocess; sys.path.insert(0,'/tmp/py')
from png import decode
def runs(px,w,y0,y1,x0,x1,thr=150):
    xs=[]
    for y in range(y0,y1):
        for x in range(x0,x1):
            p=px[y*w+x]
            if p[3]==255 and p[0]>thr and p[1]>thr: xs.append(x)
    if not xs: return []
    s=sorted(set(xs)); out=[];st=s[0];pr=s[0]
    for x in s[1:]:
        if x-pr>1: out.append((st,pr)); st=x
        pr=x
    out.append((st,pr)); return out
for n in [1,5,10,43,44,50,100]:
    r=subprocess.run(['/workspace/executable','-c','a'*n,'-o','_o.png','--silent','--margin-y','0','--margin-x','0','--has-line-number'],capture_output=True,text=True)
    w,h,ct,bd,px=decode('_o.png')
