//! Parsing of the `--range` / `--highlight-range` syntax.
//!
//! The syntax is `start:end` where either side may be omitted.  A single
//! number selects that single line.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LineRange {
    pub start: Option<usize>,
    pub end: Option<usize>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum RangeError {
    InvalidFormat,
    ParseInt(String),
}

impl std::fmt::Display for RangeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RangeError::InvalidFormat => write!(f, "Invalid range format"),
            RangeError::ParseInt(e) => write!(f, "{}", e),
        }
    }
}

fn parse_part(part: &str) -> Result<Option<usize>, RangeError> {
    if part.is_empty() {
        return Ok(None);
    }
    match part.parse::<usize>() {
        Ok(v) => Ok(Some(v)),
        Err(e) => Err(RangeError::ParseInt(e.to_string())),
    }
}

/// Parse a range string such as `3:5`, `3:`, `:5` or `3`.
pub fn parse_range(range: &str) -> Result<LineRange, RangeError> {
    let parts: Vec<&str> = range.split(':').collect();
    match parts.len() {
        1 => {
            let start = parse_part(parts[0])?;
            Ok(LineRange { start, end: None })
        }
        2 => {
            let start = parse_part(parts[0])?;
            let end = parse_part(parts[1])?;
            Ok(LineRange { start, end })
        }
        _ => Err(RangeError::InvalidFormat),
    }
}

/// Select the lines of `lines` described by `range`.
///
/// The original implementation treats the numbers as 1-based inclusive
/// boundaries, swaps them when they are given in decreasing order and falls
/// back to an empty selection when nothing matches.
pub fn select_lines(lines: &[String], range: &LineRange) -> Vec<String> {
    let total = lines.len();
    let end = range.end.unwrap_or(total);
    let (start, end) = match range.start {
        Some(s) => {
            if s <= end {
                (s, end)
            } else {
                (end, s)
            }
        }
        None => (1, end),
    };
    if start == 0 {
        return Vec::new();
    }
    let last = total.min(end);
    if start > last {
        return Vec::new();
    }
    lines[start - 1..last].to_vec()
}
