//! Minimal PNG encoder used to write the snapshot.
//!
//! The layout of the produced file matches the original tool: a single `IDAT`
//! chunk holding a zlib stream where every scanline is filtered with the
//! `Sub` filter.
use flate2::write::ZlibEncoder;
use flate2::Compression;
use std::io::Write;

pub fn encode_png(width: u32, height: u32, rgba: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(rgba.len() / 2);
    out.extend_from_slice(&[0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a]);

    let mut ihdr: Vec<u8> = Vec::new();
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.push(8); // bit depth
    ihdr.push(6); // color type RGBA
    ihdr.push(0); // compression
    ihdr.push(0); // filter
    ihdr.push(0); // interlace
    push_chunk(&mut out, b"IHDR", &ihdr);

    let stride = width as usize * 4;
    let mut raw: Vec<u8> = Vec::with_capacity((stride + 1) * height as usize);
    for y in 0..height as usize {
        let row = &rgba[y * stride..(y + 1) * stride];
        raw.push(1); // Sub filter
        let mut prev: u8 = 0;
        for x in 0..stride {
            let mut b = row[x];
            if x >= 4 {
                b = b.wrapping_sub(row[x - 4]);
            }
            let _ = prev;
            prev = b;
            raw.push(b);
        }
    }

    let mut encoder = ZlibEncoder::new(Vec::new(), Compression::new(2));
    let _ = encoder.write_all(&raw);
    let compressed = encoder.finish().unwrap_or_default();
    push_chunk(&mut out, b"IDAT", &compressed);
    push_chunk(&mut out, b"IEND", &[]);
    out
}

fn push_chunk(out: &mut Vec<u8>, kind: &[u8; 4], data: &[u8]) {
    let len = data.len() as u32;
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(kind);
    out.extend_from_slice(data);
    let mut crc = Crc32::new();
    crc.update(kind);
    crc.update(data);
    out.extend_from_slice(&crc.finalize().to_be_bytes());
}

pub struct Crc32 {
    state: u32,
}

impl Crc32 {
    pub fn new() -> Self {
        Crc32 { state: 0xffff_ffff }
    }

    pub fn update(&mut self, data: &[u8]) {
        for &b in data {
            self.state ^= b as u32;
            for _ in 0..8 {
                if self.state & 1 != 0 {
                    self.state = 0xedb8_8320 ^ (self.state >> 1);
                } else {
                    self.state >>= 1;
                }
            }
        }
    }

    pub fn finalize(&self) -> u32 {
        !self.state
    }
}

impl Default for Crc32 {
    fn default() -> Self {
        Self::new()
    }
}
