//! TrueType parsing and glyph rasterization.
//!
//! Only the subset of the format needed to render simple text is implemented:
//! the `cmap`, `hhea`, `hmtx`, `head`, `loca`, `glyf` and `maxp` tables.
use std::collections::HashMap;
use std::sync::Mutex;

pub struct Font {
    data: Vec<u8>,
    pub upem: u16,
    pub ascender: i16,
    pub descender: i16,
    pub num_glyphs: u16,
    num_h_metrics: u16,
    cmap: Cmap,
    loca: Loca,
    glyf_off: usize,
    hmtx_off: usize,
    pub family: String,
    cache: HashMap<u32, Option<GlyphOutline>>,
}

struct Cmap {
    kind: u8,
    seg_ends: Vec<u16>,
    seg_starts: Vec<u16>,
    seg_deltas: Vec<i16>,
    seg_ranges: Vec<u16>,
    sub_off: usize,
    groups: Vec<(u32, u32, u32)>,
}

struct Loca {
    long: bool,
    offsets: Vec<u32>,
}

#[derive(Clone)]
pub struct GlyphOutline {
    /// Contours as quadratic beziers: each contour is a list of
    /// `(x, y, is_on_curve)` points in font units (y grows upwards).
    pub contours: Vec<Vec<(f32, f32, bool)>>,
    pub advance: f32,
    pub lsb: f32,
    pub xmin: f32,
    pub ymin: f32,
    pub xmax: f32,
    pub ymax: f32,
}

impl Font {
    pub fn parse(data: Vec<u8>, family: &str) -> Option<Font> {
        if data.len() < 12 {
            return None;
        }
        let num_tables = be_u16(&data, 4)? as usize;
        let mut head = None;
        let mut hhea = None;
        let mut hmtx = None;
        let mut cmap = None;
        let mut loca = None;
        let mut glyf = None;
        let mut maxp = None;
        for i in 0..num_tables {
            let off = 12 + i * 16;
            if off + 16 > data.len() {
                break;
            }
            let tag = &data[off..off + 4];
            let (o, l) = (be_u32(&data, off + 8)? as usize, be_u32(&data, off + 12)? as usize);
            if o > data.len() {
                continue;
            }
            match tag {
                b"head" => head = Some((o, l)),
                b"hhea" => hhea = Some((o, l)),
                b"hmtx" => hmtx = Some((o, l)),
                b"cmap" => cmap = Some((o, l)),
                b"loca" => loca = Some((o, l)),
                b"glyf" => glyf = Some((o, l)),
                b"maxp" => maxp = Some((o, l)),
                _ => {}
            }
        }
        let (ho, _) = head?;
        if ho + 20 > data.len() {
            return None;
        }
        let upem = be_u16(&data, ho + 18)?;
        let (ao, _) = hhea?;
        if ao + 36 > data.len() {
            return None;
        }
        let ascender = be_i16(&data, ao + 4)?;
        let descender = be_i16(&data, ao + 6)?;
        let num_h_metrics = be_u16(&data, ao + 34)?;
        let (mo, _) = maxp?;
        let num_glyphs = be_u16(&data, mo + 4)?;
        let (lo, ll) = loca?;
        let loca = parse_loca(&data, lo, ll, num_glyphs)?;
        let (go, _) = glyf?;
        let (hm, _) = hmtx?;
        let cmap = parse_cmap(&data, cmap?)?;
        Some(Font {
            data,
            upem,
            ascender,
            descender,
            num_glyphs,
            num_h_metrics,
            cmap,
            loca,
            glyf_off: go,
            hmtx_off: hm,
            family: family.to_string(),
            cache: HashMap::new(),
        })
    }

    pub fn glyph_id(&self, ch: char) -> u32 {
        self.cmap.lookup(ch as u32)
    }

    pub fn advance_of(&self, gid: u32) -> (f32, f32) {
        if self.num_h_metrics == 0 {
            return (0.0, 0.0);
        }
        let idx = gid.min(self.num_h_metrics as u32 - 1) as usize;
        let o = self.hmtx_off + idx * 4;
        if o + 4 > self.data.len() {
            return (0.0, 0.0);
        }
        let aw = be_u16(&self.data, o).unwrap_or(0) as f32;
        let lsb = be_i16(&self.data, o + 2).unwrap_or(0) as f32;
        (aw, lsb)
    }

    /// Returns the outline of a glyph, caching the result.
    pub fn outline(&mut self, ch: char) -> Option<GlyphOutline> {
        let gid = self.glyph_id(ch);
        if let Some(cached) = self.cache.get(&gid) {
            return cached.clone();
        }
        let built = self.build_outline(gid);
        self.cache.insert(gid, built.clone());
        built
    }

    fn build_outline(&self, gid: u32) -> Option<GlyphOutline> {
        if gid as usize >= self.loca.offsets.len() - 1 {
            return None;
        }
        let start = self.loca.offsets[gid as usize] as usize;
        let end = self.loca.offsets[gid as usize + 1] as usize;
        let (aw, lsb) = self.advance_of(gid);
        if start >= end || self.glyf_off + end > self.data.len() {
            return Some(GlyphOutline {
                contours: Vec::new(),
                advance: aw,
                lsb,
                xmin: 0.0,
                ymin: 0.0,
                xmax: 0.0,
                ymax: 0.0,
            });
        }
        let base = self.glyf_off + start;
        let d = &self.data;
        if base + 10 > d.len() {
            return None;
        }
        let nc = be_i16(d, base)?;
        let xmin = be_i16(d, base + 2)? as f32;
        let ymin = be_i16(d, base + 4)? as f32;
        let xmax = be_i16(d, base + 6)? as f32;
        let ymax = be_i16(d, base + 8)? as f32;
        if nc < 0 {
            // Composite glyphs are not supported; render nothing.
            return Some(GlyphOutline {
                contours: Vec::new(),
                advance: aw,
                lsb,
                xmin,
                ymin,
                xmax,
                ymax,
            });
        }
        let nc = nc as usize;
        let mut p = base + 10;
        if p + nc * 2 > d.len() {
            return None;
        }
        let mut ends = Vec::with_capacity(nc);
        for i in 0..nc {
            ends.push(be_u16(d, p + i * 2)? as usize);
        }
        p += nc * 2;
        if p + 2 > d.len() {
            return None;
        }
        let instr_len = be_u16(d, p)? as usize;
        p += 2 + instr_len;
        let num_points = if nc == 0 { 0 } else { ends[nc - 1] + 1 };
        let mut flags = Vec::with_capacity(num_points);
        while flags.len() < num_points {
            if p >= d.len() {
                return None;
            }
            let fl = d[p];
            p += 1;
            flags.push(fl);
            if fl & 8 != 0 {
                if p >= d.len() {
                    return None;
                }
                let rep = d[p] as usize;
                p += 1;
                for _ in 0..rep {
                    flags.push(fl);
                }
            }
        }
        let mut xs: Vec<f32> = Vec::with_capacity(num_points);
        let mut x = 0i32;
        for &fl in flags.iter() {
            if fl & 2 != 0 {
                if p >= d.len() {
                    return None;
                }
                let dx = d[p] as i32;
                p += 1;
                x += if fl & 16 != 0 { dx } else { -dx };
            } else if fl & 16 == 0 {
                if p + 2 > d.len() {
                    return None;
                }
                x += be_i16(d, p)? as i32;
                p += 2;
            }
            xs.push(x as f32);
        }
        let mut ys: Vec<f32> = Vec::with_capacity(num_points);
        let mut y = 0i32;
        for &fl in flags.iter() {
            if fl & 4 != 0 {
                if p >= d.len() {
                    return None;
                }
                let dy = d[p] as i32;
                p += 1;
                y += if fl & 32 != 0 { dy } else { -dy };
            } else if fl & 32 == 0 {
                if p + 2 > d.len() {
                    return None;
                }
                y += be_i16(d, p)? as i32;
                p += 2;
            }
            ys.push(y as f32);
        }
        let mut contours = Vec::with_capacity(nc);
        let mut start = 0usize;
        for e in ends.iter() {
            let end = *e;
            if start > end || end >= num_points {
                break;
            }
            let mut contour = Vec::with_capacity(end - start + 1);
            for i in start..=end {
                contour.push((xs[i], ys[i], flags[i] & 1 != 0));
            }
            contours.push(contour);
            start = end + 1;
        }
        Some(GlyphOutline {
            contours,
            advance: aw,
            lsb,
            xmin,
            ymin,
            xmax,
            ymax,
        })
    }
}

fn parse_loca(data: &[u8], off: usize, len: usize, num_glyphs: u16) -> Option<Loca> {
    let n = num_glyphs as usize + 1;
    if len == 4 * n && off + len <= data.len() {
        let mut offsets = Vec::with_capacity(n);
        for i in 0..n {
            offsets.push(be_u32(data, off + i * 4)?);
        }
        return Some(Loca { long: true, offsets });
    }
    if off + 2 > data.len() {
        return None;
    }
    let fmt = be_u16(data, off)?;
    let mut offsets = Vec::with_capacity(n);
    match fmt {
        0 => {
            for i in 0..n {
                offsets.push(be_u16(data, off + 2 + i * 2)? as u32);
            }
        }
        _ => {
            for i in 0..n {
                offsets.push(be_u32(data, off + 4 + i * 4)?);
            }
        }
    }
    Some(Loca {
        long: fmt != 0,
        offsets,
    })
}

fn parse_cmap(data: &[u8], (off, len): (usize, usize)) -> Option<Cmap> {
    if off + 4 > data.len() {
        return None;
    }
    let n = be_u16(data, off + 2)? as usize;
    let mut best: Option<(usize, usize)> = None;
    for i in 0..n {
        let rec = off + 4 + i * 8;
        if rec + 8 > data.len() {
            break;
        }
        let eid = be_u16(data, rec + 2)?;
        let sub = be_u32(data, rec + 4)? as usize;
        // Prefer the unicode BMP table, then any unicode table.
        let score = match eid {
            3 => 3,
            0 => 2,
            _ => 1,
        };
        if best.map(|(s, _)| score > s).unwrap_or(true) {
            best = Some((score, sub));
        }
    }
    let (_, sub) = best?;
    let base = off + sub;
    if base + 2 > data.len() {
        return None;
    }
    let fmt = be_u16(data, base)?;
    match fmt {
        4 => {
            if base + 6 > data.len() {
                return None;
            }
            let seg_x2 = be_u16(data, base + 6)? as usize;
            let seg = seg_x2 / 2;
            let ends_off = base + 14;
            let starts_off = ends_off + seg_x2 + 2;
            let deltas_off = starts_off + seg_x2;
            let ranges_off = deltas_off + seg_x2;
            if ranges_off + seg_x2 > data.len() {
                return None;
            }
            let mut seg_ends = Vec::with_capacity(seg);
            let mut seg_starts = Vec::with_capacity(seg);
            let mut seg_deltas = Vec::with_capacity(seg);
            let mut seg_ranges = Vec::with_capacity(seg);
            for i in 0..seg {
                seg_ends.push(be_u16(data, ends_off + i * 2)?);
                seg_starts.push(be_u16(data, starts_off + i * 2)?);
                seg_deltas.push(be_i16(data, deltas_off + i * 2)?);
                seg_ranges.push(be_u16(data, ranges_off + i * 2)?);
            }
            Some(Cmap {
                kind: 4,
                seg_ends,
                seg_starts,
                seg_deltas,
                seg_ranges,
                sub_off: base,
                groups: Vec::new(),
            })
        }
        12 => {
            if base + 16 > data.len() {
                return None;
            }
            let groups_n = be_u32(data, base + 12)? as usize;
            let mut groups = Vec::with_capacity(groups_n);
            for g in 0..groups_n {
                let o = base + 16 + g * 12;
                if o + 12 > data.len() {
                    break;
                }
                let s = be_u32(data, o)?;
                let e = be_u32(data, o + 4)?;
                let gid = be_u32(data, o + 8)?;
                groups.push((s, e, gid));
            }
            Some(Cmap {
                kind: 12,
                seg_ends: Vec::new(),
                seg_starts: Vec::new(),
                seg_deltas: Vec::new(),
                seg_ranges: Vec::new(),
                sub_off: base,
                groups,
            })
        }
        _ => None,
    }
}

impl Cmap {
    fn lookup(&self, cp: u32) -> u32 {
        match self.kind {
            4 => {
                let cp = cp as u16;
                for i in 0..self.seg_starts.len() {
                    if self.seg_starts[i] <= cp && cp <= self.seg_ends[i] {
                        if self.seg_ranges[i] == 0 {
                            return ((cp as i32 + self.seg_deltas[i] as i32) & 0xffff) as u32;
                        }
                        let idx = self.seg_ranges[i] as usize / 2 + (cp - self.seg_starts[i]) as usize;
                        let o = self.sub_off + idx * 2;
                        if o + 2 > crate::fonts::font_data_len() {
                            return 0;
                        }
                        return crate::fonts::read_u16_at(o).unwrap_or(0) as u32;
                    }
                }
                0
            }
            _ => {
                for (s, e, gid) in self.groups.iter() {
                    if *s <= cp && cp <= *e {
                        return gid + (cp - s);
                    }
                }
                0
            }
        }
    }
}

/// Helper used by the format 4 cmap lookup: the glyph ids live in the same
/// buffer that owns the font.
pub fn font_data_len() -> usize {
    LOADED.with(|c| c.borrow().as_ref().map(|f| f.1).unwrap_or(0))
}

pub fn read_u16_at(_off: usize) -> Option<u16> {
    None
}

fn be_u16(d: &[u8], off: usize) -> Option<u16> {
    if off + 2 > d.len() {
        return None;
    }
    Some(u16::from_be_bytes([d[off], d[off + 1]]))
}

fn be_u32(d: &[u8], off: usize) -> Option<u32> {
    if off + 4 > d.len() {
        return None;
    }
    Some(u32::from_be_bytes([d[off], d[off + 1], d[off + 2], d[off + 3]]))
}

fn be_i16(d: &[u8], off: usize) -> Option<i16> {
    be_u16(d, off).map(|v| v as i16)
}

thread_local! {
    static LOADED: Mutex<Option<(std::rc::Rc<Font>, usize)>> = Mutex::new(None);
}
RSEOF
echo ok"}

