                        if self.seg_ranges[i] == 0 {
                            return ((cp as i32 + self.seg_deltas[i] as i32) & 0xffff) as u32;
                        }
                        let idx = self.seg_ranges[i] as usize / 2 + (cp - self.seg_starts[i]) as usize;
                        let o = self.sub_off + idx * 2;
                        if o + 2 > crate::fonts::font_data_len() {
                            return 0;
                        }
                        return crate::fonts::read_u16_at(o).unwrap_or(0) as u32;
                    }
                }
                0
            }
            _ => {
                for (s, e, gid) in self.groups.iter() {
                    if *s <= cp && cp <= *e {
                        return gid + (cp - s);
                    }
                }
                0
            }
        }
    }
}

/// Helper used by the format 4 cmap lookup: the glyph ids live in the same
/// buffer that owns the font.
pub fn font_data_len() -> usize {
    LOADED.with(|c| c.borrow().as_ref().map(|f| f.1).unwrap_or(0))
}

