//! Scanline rasterizer for glyph outlines.
use super::Font;

pub struct GlyphBitmap {
    pub w: usize,
    pub h: usize,
    /// Offset of the bitmap origin (top left) from the pen position.
    pub left: f32,
    /// Offset of the bitmap origin from the baseline (negative means above).
    pub top: f32,
    pub coverage: Vec<f32>,
}

/// Flatten a quadratic contour into a polyline (pixel coordinates, y down).
fn flatten(contour: &[(f32, f32, bool)], scale: f32, dx: f32, dy: f32) -> Vec<(f32, f32)> {
    let n = contour.len();
    if n == 0 {
        return Vec::new();
    }
    let on: Vec<bool> = contour.iter().map(|p| p.2).collect();
    let mut anchors: Vec<(f32, f32)> = Vec::new();
    let mut segs: Vec<(Vec<usize>, usize)> = Vec::new();
    let has_on = on.iter().any(|v| *v);
    if !has_on {
        for i in 0..n {
            let a = (
                (contour[i].0 + contour[(i + 1) % n].0) * 0.5,
                (contour[i].1 + contour[(i + 1) % n].1) * 0.5,
            );
            anchors.push(to_px(a, scale, dx, dy));
            segs.push((vec![i], (i + 1) % n));
        }
    } else {
        for i in 0..n {
            if !on[i] {
                continue;
            }
            let mut ctrl = Vec::new();
            let mut k = i + 1;
            while k < n && !on[k] {
                ctrl.push(k);
                k += 1;
            }
            if k < n {
                segs.push((ctrl, k));
            } else {
                segs.push((ctrl, 0));
            }
        }
        for (ctrl, _) in segs.iter() {
            let _ = ctrl;
        }
        anchors = Vec::new();
        for (ctrl, nxt) in segs.iter() {
            let start = if anchors.is_empty() {
                // find the anchor preceding this segment: the on-curve point
                0
            } else {
                0
            };
            let _ = start;
            let _ = nxt;
            let _ = ctrl;
        }
        // rebuild anchors in order
        anchors = Vec::new();
        for i in 0..n {
            if on[i] {
                anchors.push(to_px(contour[i], scale, dx, dy));
            }
        }
        segs.clear();
        for i in 0..n {
            if !on[i] {
                continue;
            }
            let mut ctrl = Vec::new();
            let mut k = i + 1;
            while k < n && !on[k] {
                ctrl.push(k);
                k += 1;
            }
