/// Locate a font on the system by family name.
pub mod system {
    use std::collections::HashMap;
    use std::path::{Path, PathBuf};
    use super::Font;

    /// Candidate directories that are scanned for font files.
    pub fn font_dirs() -> Vec<PathBuf> {
        let mut dirs = Vec::new();
        if let Some(home) = std::env::var_os("HOME") {
            let home = PathBuf::from(home);
            dirs.push(home.join(".fonts"));
            dirs.push(home.join(".local/share/fonts"));
        }
        dirs.push(PathBuf::from("/usr/local/share/fonts"));
        dirs.push(PathBuf::from("/usr/share/fonts"));
        dirs
    }

    fn walk(dir: &Path, out: &mut Vec<PathBuf>, depth: usize) {
        if depth > 4 {
            return;
        }
        let entries = match std::fs::read_dir(dir) {
            Ok(e) => e,
            Err(_) => return,
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out, depth + 1);
            } else if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
                let ext = ext.to_ascii_lowercase();
                if ext == "ttf" || ext == "otf" || ext == "ttc" {
                    out.push(path);
                }
            }
        }
    }

    /// Read the family names from the `name` table.
    fn families(data: &[u8]) -> Vec<String> {
        let mut names = Vec::new();
        if data.len() < 12 {
            return names;
        }
        let num_tables = match be_u16(data, 4) {
            Some(v) => v as usize,
            None => return names,
        };
        for i in 0..num_tables {
            let off = 12 + i * 16;
            if off + 16 > data.len() {
                break;
            }
            if &data[off..off + 4] != b"name" {
                continue;
            }
            let o = match be_u32(data, off + 8) {
                Some(v) => v as usize,
                None => continue,
            };
            if o + 6 > data.len() {
                break;
            }
            let count = be_u16(data, o + 2).unwrap_or(0) as usize;
            let storage = o + be_u16(data, o + 4).unwrap_or(0) as usize;
            let mut priority: Vec<(usize, String)> = Vec::new();
            for j in 0..count {
                let rec = o + 6 + j * 12;
                if rec + 12 > data.len() {
                    break;
                }
                let platform = be_u16(data, rec).unwrap_or(0);
                let encoding = be_u16(data, rec + 2).unwrap_or(0);
                let name_id = be_u16(data, rec + 6).unwrap_or(0);
                let length = be_u16(data, rec + 8).unwrap_or(0) as usize;
                let offset = be_u16(data, rec + 10).unwrap_or(0) as usize;
                if name_id != 1 {
                    continue;
                }
                let start = storage + offset;
                if start + length > data.len() {
                    continue;
                }
                let bytes = &data[start..start + length];
                let text = match (platform, encoding) {
                    (3, 1) | (3, 10) | (0, _) => {
                        let mut s = String::new();
                        let mut k = 0;
                        while k + 1 < bytes.len() {
                            let c = u16::from_be_bytes([bytes[k], bytes[k + 1]]);
                            if let Some(ch) = char::from_u32(c as u32) {
                                s.push(ch);
                            }
                            k += 2;
                        }
                        s
                    }
                    _ => String::from_utf_lossy(bytes).to_string(),
                };
                if !text.is_empty() {
                    priority.push((0, text));
                }
            }
            priority.sort();
            for (_, t) in priority {
                names.push(t);
            }
        }
        names
    }

    /// Load a font whose family matches `family`, falling back to `fallback`
    /// families in order.
    pub fn load(family: &str, fallbacks: &[&str]) -> Option<Font> {
        let mut files: Vec<PathBuf> = Vec::new();
        for dir in font_dirs() {
            walk(&dir, &mut files, 0);
        }
        files.sort();
        let mut index: HashMap<String, PathBuf> = HashMap::new();
        for path in &files {
            let data = match std::fs::read(path) {
                Ok(d) => d,
                Err(_) => continue,
            };
            for name in families(&data) {
                let key = name.trim().to_ascii_lowercase();
                index.entry(key).or_insert_with(|| path.clone());
            }
        }
        let mut wanted: Vec<String> = vec![family.trim().to_ascii_lowercase()];
        for f in fallbacks {
            wanted.push(f.trim().to_ascii_lowercase());
        }
        for w in wanted {
            if let Some(path) = index.get(&w) {
                if let Ok(data) = std::fs::read(path) {
                    if let Some(font) = Font::parse(data, family) {
                        return Some(font);
                    }
                }
            }
        }
        // Fall back to the first font that can be parsed.
        for path in &files {
            if let Ok(data) = std::fs::read(path) {
                if let Some(font) = Font::parse(data, family) {
                    return Some(font);
                }
            }
        }
        None
    }
}
