/// Flatten a quadratic contour into a polyline in pixel space (y grows down).
fn flatten(contour: &[(f32, f32, bool)], scale: f32, dx: f32, dy: f32) -> Vec<(f32, f32)> {
    let n = contour.len();
    let mut poly: Vec<(f32, f32)> = Vec::new();
    if n == 0 {
        return poly;
    }
    let to_px = |p: (f32, f32, bool)| -> (f32, f32) { (p.0 * scale + dx, -p.1 * scale + dy) };
    let pts: Vec<(f32, f32)> = contour.iter().map(|p| to_px(*p)).collect();
    let on: Vec<bool> = contour.iter().map(|p| p.2).collect();
    let mut anchors: Vec<usize> = Vec::new();
    for i in 0..n {
        if on[i] {
            anchors.push(i);
        }
    }
    let start;
    let mut idx;
    let mut consumed;
    if anchors.is_empty() {
        // Every point is off-curve: the anchor is the midpoint between
        // consecutive points.
        let mid = ((pts[0].0 + pts[n - 1].0) * 0.5, (pts[0].1 + pts[n - 1].1) * 0.5);
        poly.push(mid);
        start = 0usize;
        idx = 1 % n;
        consumed = 0usize;
    } else {
        start = anchors[0];
        poly.push(pts[start]);
        idx = (start + 1) % n;
        consumed = 1usize;
    }
    let mut guard = 0usize;
    while consumed < n + 1 && guard < 8 * n + 16 {
        guard += 1;
        let mut ctrl: Vec<(f32, f32)> = Vec::new();
        let mut steps = 0usize;
        while !on[idx] && steps < n {
            ctrl.push(pts[idx]);
            idx = (idx + 1) % n;
            steps += 1;
            guard += 1;
        }
        consumed += steps;
        if steps == n {
            break;
        }
        let end = pts[idx];
        consumed += 1;
        emit_quads(&mut poly, poly.last().copied().unwrap_or(end), &ctrl, end);
