        if !anchors.is_empty() && idx == start {
            break;
        }
        if anchors.is_empty() && consumed >= n + 1 {
            break;
        }
    }
    poly
}

fn emit_quads(poly: &mut Vec<(f32, f32)>, start: (f32, f32), ctrl: &[(f32, f32)], end: (f32, f32)) {
