    pub fn fill_rect(&mut self, x0: f32, y0: f32, x1: f32, y1: f32, color: &Color) {
        let (r, g, b, a) = color.rgba();
        if a == 0 {
            return;
        }
        let x0 = x0.floor().max(0.0) as usize;
        let y0 = y0.floor().max(0.0) as usize;
        let x1 = (x1.ceil() as usize).min(self.w);
        let y1 = (y1.ceil() as usize).min(self.h);
        for y in y0..y1 {
