    /// Fill a rounded rectangle, blending with coverage based antialiasing.
    pub fn fill_rounded_rect(&mut self, x0: f32, y0: f32, x1: f32, y1: f32, radius: f32, color: &Color) {
        let (r, g, b, a) = color.rgba();
        if a == 0 {
            return;
        }
        let xa = x0.floor().max(0.0) as usize;
        let ya = y0.floor().max(0.0) as usize;
        let xb = (x1.ceil() as usize).min(self.w);
        let yb = (y1.ceil() as usize).min(self.h);
        if xb <= xa || yb <= ya {
            return;
        }
        let radius = radius.max(0.0);
        let cx0 = x0 + radius;
        let cy0 = y0 + radius;
        let cx1 = x1 - radius;
        let cy1 = y1 - radius;
        for y in ya..yb {
            let py = y as f32 + 0.5;
            for x in xa..xb {
                let px = x as f32 + 0.5;
                let cov = coverage(px, py, x0, y0, x1, y1, radius, cx0, cy0, cx1, cy1);
                if cov <= 0.0 {
                    continue;
                }
                let alpha = ((a as u32 as f32 * cov) as u32).min(255) as u8;
                self.blend(x, y, (r, g, b, alpha));
            }
        }
    }

    /// Draw a glyph bitmap with the given color.
    pub fn draw_glyph(&mut self, bmp: &crate::fonts::raster::GlyphBitmap, ox: f32, oy: f32, color: (u8, u8, u8, u8)) {
        let (r, g, b, a) = color;
        for y in 0..bmp.h {
            let py = oy + bmp.top + y as f32;
            let yi = py.floor() as i64;
            let fy = py - yi as f32;
            for x in 0..bmp.w {
                let cov = bmp.coverage[y * bmp.w + x];
                if cov <= 0.0 {
                    continue;
                }
                let px = ox + bmp.left + x as f32;
                let xi = px.floor() as i64;
                let fx = px - xi as f32;
                let c00 = cov * (1.0 - fx) * (1.0 - fy);
                let c10 = cov * fx * (1.0 - fy);
                let c01 = cov * (1.0 - fx) * fy;
                let c11 = cov * fx * fy;
                for (dx, dy, c) in [
                    (0i64, 0i64, c00),
                    (1, 0, c10),
                    (0, 1, c01),
                    (1, 1, c11),
                ] {
                    if c <= 0.0001 {
                        continue;
                    }
                    let xx = xi + dx;
                    let yy = yi + dy;
                    if xx < 0 || yy < 0 {
                        continue;
