//! Linear gradient backgrounds.
use crate::config::{Background, GradientPoint, GradientStop, Position};
use crate::utils::color::Color;

pub struct Gradient {
    pub start: (f32, f32),
    pub end: (f32, f32),
    pub stops: Vec<(f32, Color)>,
}

fn resolve(p: &GradientPoint, max: f32) -> f32 {
    match (&p.x, &p.y) {
        (Position::Max, _) => max,
        (_, Position::Max) => max,
        (Position::Value(v), _) => *v,
    }
}

impl Gradient {
    pub fn from_config(bg: &Background, width: f32, height: f32) -> Option<Gradient> {
        match bg {
            Background::Solid(hex) => Some(Gradient {
                start: (0.0, 0.0),
                end: (width, 0.0),
                stops: vec![(0.0, Color::from_hex(hex))],
            }),
            Background::Gradient { start, end, stops } => {
                if stops.is_empty() {
                    panic!("called `Option::unwrap()` on a `None` value");
                }
                let s = (resolve(start, width), resolve_y(start, height));
                let e = (resolve(end, width), resolve_y(end, height));
                Some(Gradient {
                    start: s,
                    end: e,
                    stops: stops
                        .iter()
                        .map(|st: &GradientStop| (st.position, Color::from_hex(&st.color)))
                        .collect(),
                })
            }
        }
    }

    /// Color at a pixel center.
    pub fn color_at(&self, x: f32, y: f32) -> (u8, u8, u8, u8) {
        if self.stops.len() == 1 {
            return self.stops[0].1.rgba();
        }
        let dx = self.end.0 - self.start.0;
        let dy = self.end.1 - self.start.1;
        let len2 = dx * dx + dy * dy;
        let t = if len2 <= f32::EPSILON {
            0.0
        } else {
            ((x - self.start.0) * dx + (y - self.start.1) * dy) / len2
        };
        let t = t.clamp(0.0, 1.0);
        let mut i = 0;
        while i + 1 < self.stops.len() && t > self.stops[i + 1].0 {
            i += 1;
        }
        let (p0, c0) = self.stops[i];
        let (p1, c1) = if i + 1 < self.stops.len() {
            self.stops[i + 1]
        } else {
            (p0 + 1.0, c0)
        };
        let local = if (p1 - p0).abs() < f32::EPSILON {
            0.0
        } else {
            ((t - p0) / (p1 - p0)).clamp(0.0, 1.0)
        };
        let mix = |a: u8, b: u8| -> u8 { (a as f32 + (b as f32 - a as f32) * local).round() as u8 };
        (
            mix(c0.r, c1.r),
            mix(c0.g, c1.g),
            mix(c0.b, c1.b),
            mix(c0.a, c1.a),
        )
    }
}

fn resolve_y(p: &GradientPoint, _max: f32) -> f32 {
    match &p.y {
        Position::Value(v) => *v,
        Position::Max => 0.0,
    }
}
