//! Background gradients.
use crate::config::{Background, GradientPoint, GradientStop, Position};
use crate::render::gradient::Gradient;
use crate::utils::color::Color;

/// A resolved background ready to be painted.
pub struct ResolvedBackground {
    gradient: Gradient,
}

fn resolve_x(p: &GradientPoint, max: f32) -> f32 {
    match &p.x {
        Position::Value(v) => *v,
        Position::Max => max,
    }
}

fn resolve_y(p: &GradientPoint, max: f32) -> f32 {
    match &p.y {
        Position::Value(v) => *v,
        Position::Max => max,
    }
}

impl ResolvedBackground {
    pub fn new(bg: &Background, width: f32, height: f32) -> ResolvedBackground {
        match bg {
            Background::Solid(hex) => ResolvedBackground {
                gradient: Gradient {
                    start: (0.0, 0.0),
                    end: (width, 0.0),
                    stops: vec![(0.0, Color::from_hex(hex))],
                },
            },
            Background::Gradient { start, end, stops } => ResolvedBackground {
                gradient: Gradient {
                    start: (resolve_x(start, width), resolve_y(start, height)),
                    end: (resolve_x(end, width), resolve_y(end, height)),
                    stops: stops
                        .iter()
                        .map(|st: &GradientStop| (st.position, Color::from_hex(&st.color)))
                        .collect(),
                },
            },
        }
    }

    /// Color of the first gradient stop.
    ///
    /// The original implementation unwraps the first stop, which panics when
    /// the gradient was defined without any stop at all.
    pub fn first_color(&self) -> (u8, u8, u8, u8) {
        let stops = &self.gradient.stops;
        let stop = stops.iter().next();
        stop.unwrap().1.rgba()
    }

    pub fn color_at(&self, x: f32, y: f32) -> (u8, u8, u8, u8) {
        self.gradient.color_at(x, y)
    }
}
