//! The window container: background, shadow, border and rounded corners.
use crate::config::{BorderConfig, MarginConfig, ShadowConfig, WindowConfig};
use crate::render::Canvas;
use crate::utils::color::Color;

/// Geometry of the window in device pixels.
pub struct Geometry {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}

pub struct Container {
    pub margin: MarginConfig,
    pub shadow: ShadowConfig,
    pub border: BorderConfig,
    pub radius: f32,
    pub mac_window_bar: bool,
}

impl Container {
    pub fn new(config: &WindowConfig) -> Container {
        Container {
            margin: config.margin,
            shadow: config.shadow.clone(),
            border: config.border.clone(),
            radius: config.radius,
            mac_window_bar: config.mac_window_bar,
        }
    }

    /// Size of the canvas in pixels.
    pub fn canvas_size(&self, content_w: f32, content_h: f32, scale: u32) -> (usize, usize) {
        let margin_x = self.margin.x * scale as f32;
        let margin_y = self.margin.y * scale as f32;
        let width = (content_w * scale as f32 + margin_x * 2.0).ceil();
        let height_units = self.margin.y + (if self.margin.y >= 82.0 { 72.0 } else { 0.0 });
        let height = (content_h * scale as f32 + margin_y + height_units * scale as f32).floor();
        // The layout is expressed in `u32` pixel counts; a huge margin cannot
        // be converted and the original implementation unwraps the result.
        let w = u32::try_from(width).ok();
        let h = u32::try_from(height).ok();
        (w.unwrap() as usize, h.unwrap() as usize)
    }

    pub fn geometry(&self, content_w: f32, content_h: f32, scale: u32) -> Geometry {
        let margin_x = self.margin.x * scale as f32;
        let margin_y = self.margin.y * scale as f32;
        Geometry {
            x: margin_x,
            y: margin_y,
            width: content_w * scale as f32,
            height: content_h * scale as f32,
        }
    }

    /// Paint the drop shadow behind the window.
    pub fn paint_shadow(&self, canvas: &mut Canvas, geo: &Geometry, scale: u32) {
        let radius = self.shadow.radius * scale as f32;
        if radius <= 0.0 {
            return;
        }
        let color = Color::from_hex(&self.shadow.color);
        let expand = radius;
        let x0 = geo.x - expand;
        let y0 = geo.y - expand + radius;
        let x1 = geo.x + geo.width + expand;
        let y1 = geo.y + geo.height + expand + radius;
        blur_rect(canvas, x0, y0, x1, y1, radius, color);
    }

    /// Paint the window body with its rounded corners.
    pub fn paint_window(&self, canvas: &mut Canvas, geo: &Geometry, bg_color: (u8, u8, u8, u8)) {
        let scale_radius = self.radius;
        let radius = scale_radius * 3.0;
        let color = Color::new(bg_color.0, bg_color.1, bg_color.2, 255);
        canvas.fill_rounded_rect(geo.x, geo.y, geo.x + geo.width, geo.y + geo.height, radius, &color);
    }

    /// Paint the border inset by one border width.
    pub fn paint_border(&self, canvas: &mut Canvas, geo: &Geometry, scale: u32) {
        let width = (self.border.width * scale as f32).max(0.0);
        if width <= 0.0 {
            return;
        }
        let color = Color::from_hex(&self.border.color);
        let inset = width;
        let x0 = geo.x + inset;
        let y0 = geo.y + inset;
        let x1 = geo.x + geo.width - inset;
        let y1 = geo.y + geo.height - inset;
        // top
        canvas.fill_rect(x0, y0, x1, y0 + width, &color);
        // bottom
        canvas.fill_rect(x0, y1 - width, x1, y1, &color);
        // left
        canvas.fill_rect(x0, y0, x0 + width, y1, &color);
        // right
        canvas.fill_rect(x1 - width, y0, x1, y1, &color);
    }
}

/// Draw a blurred rectangle by convolving an alpha mask with a gaussian.
fn blur_rect(canvas: &mut Canvas, x0: f32, y0: f32, x1: f32, y1: f32, sigma: f32, color: Color) {
    let pad = (sigma * 3.0).ceil() as usize;
    let ox = x0.floor() as i64 - pad as i64;
    let oy = y0.floor() as i64 - pad as i64;
    let w = (x1.ceil() as i64 + pad as i64 - ox).max(1) as usize;
    let h = (y1.ceil() as i64 + pad as i64 - oy).max(1) as usize;
    if w > 8192 || h > 8192 {
        return;
    }
    let mut mask = vec![0.0f32; w * h];
    let rx = x0.floor() as i64;
    let ry = y0.floor() as i64;
    for y in 0..h {
        for x in 0..w {
            let px = (ox + x as i64) as f32;
            let py = (oy + y as i64) as f32;
            let inside = px >= rx as f32 && px < (rx as f32 + (x1 - x0)) && py >= ry as f32 && py < (ry as f32 + (y1 - y0));
            if inside {
                mask[y * w + x] = 1.0;
            }
        }
    }
    // Two box blur passes approximate a gaussian.
    let radius = ((sigma / 2.0).ceil() as usize).max(1);
    box_blur(&mut mask, w, h, radius);
    box_blur(&mut mask, w, h, radius);
    let (r, g, b, a) = color.rgba();
    for y in 0..h {
        let cy = oy + y as i64;
        if cy < 0 {
            continue;
        }
        let cy = cy as usize;
        if cy >= canvas.h {
            continue;
        }
        for x in 0..w {
            let cx = ox + x as i64;
            if cx < 0 {
                continue;
            }
            let cx = cx as usize;
            if cx >= canvas.w {
                continue;
            }
            let v = mask[y * w + x];
            if v <= 0.0001 {
                continue;
            }
            let alpha = ((a as u32 as f32 * v) as u32).min(255) as u8;
            canvas.blend(cx, cy, (r, g, b, alpha));
        }
    }
}

fn box_blur(mask: &mut [f32], w: usize, h: usize, radius: usize) {
    if radius == 0 {
        return;
    }
    let mut tmp = vec![0.0f32; w * h];
    // horizontal
    for y in 0..h {
        let row = &mask[y * w..(y + 1) * w];
        let mut sum = 0.0f32;
        let mut count = 0usize;
        for x in 0..w {
            sum += row[x];
            count += 1;
            if x >= radius * 2 + 1 {
                sum -= row[x - radius * 2 - 1];
                count -= 1;
            }
            tmp[y * w + x] = sum / count.max(1) as f32;
        }
    }
    // vertical
    for x in 0..w {
        let mut sum = 0.0f32;
        let mut count = 0usize;
        for y in 0..h {
            sum += tmp[y * w + x];
            count += 1;
            if y >= radius * 2 + 1 {
                sum -= tmp[(y - radius * 2 - 1) * w + x];
                count -= 1;
            }
            mask[y * w + x] = sum / count.max(1) as f32;
        }
    }
}
