        if ln: out.append(('ln',min(ln),max(ln)))
        if code_ink: out.append(('code',min(code_ink),max(code_ink)))
    return (w,h),out
for sl in [1,10,100,1000]:
    print(sl, measure(['--start-line-number',str(sl)]))
EOF"}

