//! macOS style window bar with the three traffic light dots and a title.
use crate::fonts::Font;
use crate::render::Canvas;
use crate::utils::color::Color;

pub const BAR_HEIGHT: f32 = 24.0;
pub const DOT_RADIUS: f32 = 6.0;
pub const DOT_SPACING: f32 = 16.0;
pub const DOT_FIRST_X: f32 = 16.0;
pub const DOT_CY: f32 = 22.0;

const DOTS: [(&str, u8, u8, u8); 3] = [
    ("#ff5e57", 255, 94, 87),
    ("#ffba2e", 255, 186, 46),
    ("#2bc841", 43, 200, 65),
];

pub struct MacWindowBar;

impl MacWindowBar {
    pub fn height() -> f32 {
        BAR_HEIGHT
    }

    /// Paint the three dots and the optional title.
    pub fn paint(
        canvas: &mut Canvas,
        window_x: f32,
        window_y: f32,
        window_w: f32,
        scale: u32,
        title: Option<&str>,
        title_font: &mut Font,
        title_color: &Color,
    ) {
        let s = scale as f32;
        for (i, (_hex, r, g, b)) in DOTS.iter().enumerate() {
            let cx = window_x + (DOT_FIRST_X + DOT_RADIUS + (i as f32) * DOT_SPACING) * s;
            let cy = window_y + DOT_CY * s;
            let rad = DOT_RADIUS * s;
            fill_circle(canvas, cx, cy, rad, (*r, *g, *b, 255));
        }
        if let Some(text) = title {
            if text.is_empty() {
                return;
            }
            let size = 10.0 * s;
            let (w, _h) = measure_text(title_font, text, size);
            let x = window_x + window_w * 0.5 - w * 0.5;
            let baseline = window_y + (BAR_HEIGHT + 0.3333) * s;
            draw_text(canvas, title_font, text, x, baseline, size, title_color.rgba(), 255);
        }
    }
}

/// Measure the width of `text` when rendered at `size` pixels per em.
pub fn measure_text(font: &mut Font, text: &str, size: f32) -> (f32, f32) {
    let mut x = 0.0;
    let mut max_asc = 0.0f32;
    let mut max_desc = 0.0f32;
    for ch in text.chars() {
        if let Some(o) = font.outline(ch) {
            x += o.advance / font.upem as f32 * size;
            let asc = o.ymax / font.upem as f32 * size;
            let desc = -o.ymin / font.upem as f32 * size;
            if asc > max_asc {
                max_asc = asc;
            }
            if desc > max_desc {
                max_desc = desc;
            }
        }
    }
    (x, max_asc + max_desc)
}

/// Draw a string with the baseline at `baseline`.
pub fn draw_text(
    canvas: &mut Canvas,
    font: &mut Font,
    text: &str,
    x: f32,
    baseline: f32,
    size: f32,
    color: (u8, u8, u8, u8),
    alpha: u8,
) {
    let mut pen = x;
    let color = (color.0, color.1, color.2, alpha);
    for ch in text.chars() {
        let advance = font.advance_em(ch) * size;
        if let Some(bmp) = crate::fonts::raster::rasterize(&font.outline(ch).unwrap_or(crate::fonts::GlyphOutline::empty(0.0, 0.0)), font.upem, size, 0.0, 0.0) {
            canvas.draw_glyph(&bmp, pen + bmp.left, baseline + bmp.top, color);
        }
        pen += advance;
    }
}

fn fill_circle(canvas: &mut Canvas, cx: f32, cy: f32, radius: f32, color: (u8, u8, u8, u8)) {
    let x0 = (cx - radius).floor().max(0.0) as usize;
    let y0 = (cy - radius).floor().max(0.0) as usize;
    let x1 = ((cx + radius).ceil() as usize).min(canvas.w);
    let y1 = ((cy + radius).ceil() as usize).min(canvas.h);
    for y in y0..y1 {
        for x in x0..x1 {
            let dx = x as f32 + 0.5 - cx;
            let dy = y as f32 + 0.5 - cy;
            let d = (dx * dx + dy * dy).sqrt() - radius;
            let cov = if d <= -0.5 {
                1.0
            } else if d >= 0.5 {
                0.0
            } else {
                0.5 - d
            };
            if cov <= 0.0 {
                continue;
            }
            let a = ((color.3 as u32 as f32 * cov) as u32).min(255) as u8;
            canvas.blend(x, y, (color.0, color.1, color.2, a));
        }
    }
}
