//! Simple syntax highlighter.
//!
//! The original tool ships with a full syntax highlighting engine; this module
//! implements a compact tokeniser driven by per language tables which
//! reproduces the most common scopes of the bundled theme.
use crate::utils::color::Color;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scope {
    Plain,
    Comment,
    String,
    Keyword,
    Type,
    Function,
    Number,
    Operator,
    Bracket,
}

/// The `candy` theme.
pub struct Theme {
    pub foreground: Color,
    pub comment: Color,
    pub string: Color,
    pub keyword: Color,
    pub type_name: Color,
    pub function: Color,
    pub constant: Color,
    pub operator: Color,
    pub bracket: Color,
    pub line_number: Color,
    pub breadcrumbs: Color,
}

impl Theme {
    pub fn candy() -> Theme {
        Theme {
            foreground: Color::from_hex("#f8f8f2"),
            comment: Color::from_hex("#6272a4"),
            string: Color::from_hex("#f1fa8c"),
            keyword: Color::from_hex("#8be9fd"),
            type_name: Color::from_hex("#66d9ef"),
            function: Color::from_hex("#50fa7b"),
            constant: Color::from_hex("#bd93f9"),
            operator: Color::from_hex("#ff79c6"),
            bracket: Color::from_hex("#ffffff"),
            line_number: Color::from_hex("#495162"),
            breadcrumbs: Color::from_hex("#80848b"),
        }
    }

    pub fn find(name: &str) -> Option<Theme> {
        if name.eq_ignore_ascii_case("candy") {
            Some(Theme::candy())
        } else {
            None
        }
    }

    pub fn color(&self, scope: Scope) -> Color {
        match scope {
            Scope::Plain => self.foreground,
            Scope::Comment => self.comment,
            Scope::String => self.string,
            Scope::Keyword => self.keyword,
            Scope::Type => self.type_name,
            Scope::Function => self.function,
            Scope::Number => self.constant,
            Scope::Operator => self.operator,
            Scope::Bracket => self.bracket,
        }
    }
}

#[derive(Debug, Clone)]
pub struct LangDef {
    pub id: &'static str,
    pub extensions: &'static [&'static str],
    pub line_comment: &'static [&'static str],
    pub block_comment: Option<(&'static str, &'static str)>,
    pub string_delims: &'static [char],
    pub keywords: &'static [&'static str],
    pub keywords2: &'static [&'static str],
    pub types: &'static [&'static str],
    pub operators: &'static [&'static str],
    pub brackets: &'static [char],
}

macro_rules! lang {
    ($id:expr, $exts:expr, $lc:expr, $bc:expr, $sd:expr, $kw:expr, $kw2:expr, $ty:expr, $op:expr, $br:expr) => {
        LangDef {
            id: $id,
            extensions: $exts,
            line_comment: $lc,
            block_comment: $bc,
            string_delims: $sd,
            keywords: $kw,
            keywords2: $kw2,
            types: $ty,
            operators: $op,
            brackets: $br,
        }
    };
}

