/// Detect the language from a file name.
pub fn detect_language(path: &str) -> Option<&'static LangDef> {
    let file = path.rsplit(['/']).next().unwrap_or(path);
    let ext = file.rsplit('.').next().unwrap_or("");
    if ext.is_empty() || ext == file {
        return None;
    }
    LANGS
        .iter()
        .find(|l| l.extensions.iter().any(|e| e.eq_ignore_ascii_case(ext)))
}

/// Find a language definition by identifier.
pub fn find_language(name: &str) -> Option<&'static LangDef> {
    let name = name.trim().to_ascii_lowercase();
    LANGS.iter().find(|l| l.id == name)
}

/// Highlight `code` returning one scope per character.
pub fn highlight(def: &LangDef, code: &str) -> Vec<Vec<Scope>> {
    let chars: Vec<char> = code.chars().collect();
    let mut scopes = vec![Scope::Plain; chars.len()];
    let bc = def.block_comment;
    let mut i = 0usize;
    let mut prev_word: Option<String> = None;
    while i < chars.len() {
        let rest: String = chars[i..].iter().collect();
        // line comment
        if def
            .line_comment
            .iter()
            .any(|s| rest.starts_with(s))
        {
            while i < chars.len() && chars[i] != '\n' {
                scopes[i] = Scope::Comment;
                i += 1;
            }
            prev_word = None;
            continue;
        }
        // block comment
        if let Some((open, close)) = bc {
            if rest.starts_with(open) {
                let mut depth = 1;
                let n = open.len();
                for k in 0..n {
                    if i + k < chars.len() {
                        scopes[i + k] = Scope::Comment;
                    }
                }
                i += n;
                while i < chars.len() && depth > 0 {
                    let r2: String = chars[i..].iter().collect();
                    if r2.starts_with(open) {
                        depth += 1;
                        for k in 0..n {
                            if i + k < chars.len() {
                                scopes[i + k] = Scope::Comment;
                            }
                        }
                        i += n;
                        continue;
                    }
                    if r2.starts_with(close) {
                        depth -= 1;
                        for k in 0..close.len() {
                            if i + k < chars.len() {
                                scopes[i + k] = Scope::Comment;
                            }
                        }
                        i += close.len();
                        continue;
                    }
                    scopes[i] = Scope::Comment;
                    i += 1;
                }
                prev_word = None;
                continue;
            }
        }
        // strings
        if def.string_delims.contains(&chars[i]) {
            let delim = chars[i];
            scopes[i] = Scope::String;
            i += 1;
            while i < chars.len() {
                if chars[i] == '\\' && i + 1 < chars.len() {
                    scopes[i] = Scope::String;
                    scopes[i + 1] = Scope::String;
                    i += 2;
                    continue;
                }
                scopes[i] = Scope::String;
                if chars[i] == delim {
                    i += 1;
                    break;
                }
                if chars[i] == '\n' {
                    i += 1;
                    break;
                }
                i += 1;
            }
            prev_word = None;
            continue;
        }
        // identifiers
        if chars[i].is_alphabetic() || chars[i] == '_' || chars[i] == '#' || chars[i] == '@' {
            let start = i;
            while i < chars.len()
                && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '!')
            {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            let scope = classify(def, &word, &prev_word, start, &chars, i);
            for k in start..i {
                scopes[k] = scope;
            }
            prev_word = Some(word);
            continue;
        }
        // numbers
        if chars[i].is_ascii_digit() {
            let start = i;
            while i < chars.len()
                && (chars[i].is_ascii_alphanumeric() || chars[i] == '.' || chars[i] == '_')
            {
                i += 1;
            }
            for k in start..i {
                scopes[k] = Scope::Number;
            }
            prev_word = None;
            continue;
        }
        // brackets
        if def.brackets.contains(&chars[i]) {
            scopes[i] = Scope::Bracket;
            prev_word = None;
            i += 1;
            continue;
        }
        // operators
        if def.operators.iter().any(|o| rest.starts_with(o)) {
            let best = def
                .operators
                .iter()
                .filter(|o| rest.starts_with(**o))
                .map(|o| o.len())
                .max()
                .unwrap_or(1);
            for k in i..i + best {
                if k < chars.len() {
                    scopes[k] = Scope::Operator;
                }
            }
            i += best;
            prev_word = None;
            continue;
        }
        prev_word = None;
        i += 1;
    }
    scopes
}

fn classify(
    def: &LangDef,
    word: &str,
    prev_word: &Option<String>,
    start: usize,
    chars: &[char],
    end: usize,
) -> Scope {
    if def.keywords.contains(&word) {
        return Scope::Keyword;
    }
    if def.types.contains(&word) {
        return Scope::Type;
    }
    if def.keywords2.contains(&word) {
        return Scope::Operator;
    }
    // A word followed by `(` is a function name.
    let mut k = end;
    while k < chars.len() && chars[k].is_whitespace() {
        k += 1;
    }
    if k < chars.len() && chars[k] == '(' && prev_word.as_deref() != Some(".") {
        // methods after a dot are keywords in this theme
        if let Some(prev) = prev_word {
            let _ = prev;
        }
        return Scope::Function;
    }
    // Constants are written in SCREAMING_SNAKE_CASE.
    if word.chars().all(|c| c.is_uppercase() || c == '_') && word.chars().any(|c| c.is_uppercase())
    {
        return Scope::Number;
    }
    Scope::Plain
}
