//! The code block: highlighted text, line numbers and line markers.
use crate::fonts::Font;
use crate::highlight::{highlight, LangDef, Scope, Theme};
use crate::render::Canvas;

/// Layout constants, expressed in "units" (multiplied by the scale factor).
pub const FONT_SIZE: f32 = 12.5;
pub const LAYOUT_ADVANCE: f32 = 7.32421875;
pub const LINE_HEIGHT: f32 = 18.0;
pub const PADDING_X: f32 = 16.0;
pub const MIN_CONTENT_WIDTH: f32 = 354.0;
pub const CODE_AREA_PADDING: f32 = 30.0;
pub const BASELINE_OFFSET: f32 = 27.3333;
pub const BREADCRUMBS_HEIGHT: f32 = 15.0;

/// Width of the line number gutter for `digits` digits.
pub fn gutter_width(digits: usize) -> f32 {
    if digits == 0 {
        0.0
    } else {
        10.0 + 9.0 * digits as f32
    }
}

/// Opacity of the code text when line numbers are displayed.  The original
/// implementation reduces the opacity depending on the width of the gutter.
pub fn line_number_alpha(digits: usize) -> u8 {
    match digits {
        0 => 255,
        1 => 222,
        2 => 201,
        3 => 191,
        4 => 194,
        5 => 207,
        6 => 230,
        7 => 241,
        8 => 213,
        _ => 196,
    }
}

/// Number of columns a line occupies once tabs are expanded.
pub fn line_columns(line: &str) -> usize {
    let mut cols = 0usize;
    for ch in line.chars() {
        if ch == '\t' {
            cols += 2;
        } else {
            cols += 1;
        }
    }
    cols
}

/// Number of columns of the leading whitespace of a line.
pub fn indent_columns(line: &str) -> usize {
    let mut cols = 0usize;
    for ch in line.chars() {
        match ch {
            ' ' => cols += 1,
            '\t' => cols += 2,
            _ => break,
        }
    }
    cols
}

/// Strip the common indentation of all lines.
pub fn dedent(lines: &[String]) -> Vec<String> {
    let mut min_indent = usize::MAX;
    for line in lines {
        let trimmed = line.trim_start();
        if trimmed.is_empty() {
            continue;
        }
        let ind = indent_columns(line);
        if ind < min_indent {
            min_indent = ind;
        }
    }
    if min_indent == usize::MAX {
        min_indent = 0;
    }
    lines
        .iter()
        .map(|line| {
            let mut cols = 0usize;
            let mut idx = 0usize;
            let chars: Vec<char> = line.chars().collect();
            while idx < chars.len() && cols < min_indent {
                match chars[idx] {
                    ' ' => {
                        cols += 1;
                        idx += 1;
                    }
                    '\t' => {
                        cols += 2;
                        idx += 1;
                    }
                    _ => break,
                }
            }
            chars[idx..].iter().collect::<String>()
        })
        .collect()
}

pub struct CodeBlock {
    pub lines: Vec<String>,
    pub scopes: Vec<Vec<Scope>>,
    pub columns: usize,
}

impl CodeBlock {
    pub fn new(lines: Vec<String>, lang: Option<&'static LangDef>, code: &str) -> CodeBlock {
        let lines = dedent(&lines);
        let scopes = match lang {
            Some(def) => highlight(def, code),
            None => Vec::new(),
        };
        let columns = lines.iter().map(|l| line_columns(l)).max().unwrap_or(0);
        CodeBlock {
            lines,
            scopes,
            columns,
        }
    }

    /// Content width in units.
    pub fn content_width(&self, has_line_numbers: bool, start_line: usize) -> f32 {
        let digits = if has_line_numbers {
            digit_count(start_line + self.lines.len().saturating_sub(1))
        } else {
            0
        };
        let gutter = gutter_width(digits);
        let text = self.columns as f32 * LAYOUT_ADVANCE;
        let width = PADDING_X * 2.0 + gutter + text;
        if width < MIN_CONTENT_WIDTH {
            MIN_CONTENT_WIDTH
        } else {
            width
        }
    }

    /// Content height in units.
    pub fn content_height(&self, breadcrumbs: bool) -> f32 {
        CODE_AREA_PADDING + self.lines.len() as f32 * LINE_HEIGHT + if breadcrumbs { BREADCRUMBS_HEIGHT } else { 0.0 }
    }

    pub fn code_area_top(&self, breadcrumbs: bool) -> f32 {
        crate::components::mac_window_bar::MacWindowBar::height()
            + if breadcrumbs { BREADCRUMBS_HEIGHT } else { 0.0 }
    }

    /// Paint the code block.
    #[allow(clippy::too_many_arguments)]
    pub fn paint(
        &self,
        canvas: &mut Canvas,
        window_x: f32,
        window_y: f32,
        window_w: f32,
        scale: u32,
        theme: &Theme,
        font: &mut Font,
        lang: Option<&'static LangDef>,
        code: &str,
        has_line_numbers: bool,
        start_line: usize,
        line_number_color: &crate::utils::color::Color,
        highlight_ranges: &[(usize, usize, crate::utils::color::Color)],
    ) {
        let s = scale as f32;
        let size = FONT_SIZE * s;
        let digits = if has_line_numbers {
            digit_count(start_line + self.lines.len().saturating_sub(1))
        } else {
            0
        };
        let gutter = gutter_width(digits);
        let code_cell_x = window_x + (PADDING_X + gutter) * s;
        let top = window_y + self.code_area_top(false) * s;
        let baseline0 = window_y
            + (crate::components::mac_window_bar::MacWindowBar::height() + BASELINE_OFFSET) * s;
        // Highlight ranges are painted over the whole window width.
        for (start, end, color) in highlight_ranges {
            let y0 = window_y
                + (crate::components::mac_window_bar::MacWindowBar::height()
                    + (start.saturating_sub(1)) as f32 * LINE_HEIGHT)
                    * s;
            let y1 = window_y
                + (crate::components::mac_window_bar::MacWindowBar::height()
                    + (*end as f32) * LINE_HEIGHT)
                    * s;
            canvas.fill_rect(window_x, y0, window_x + window_w, y1, color);
        }
        let alpha = line_number_alpha(digits);
        for (i, line) in self.lines.iter().enumerate() {
            let baseline = baseline0 + i as f32 * LINE_HEIGHT * s;
            // line number
            if has_line_numbers {
                let text = (start_line + i).to_string();
                let ln_color = line_number_color.rgba();
                let w = crate::components::mac_window_bar::measure_text(font, &text, size).0;
                let right = code_cell_x - 12.0 * s;
                crate::components::mac_window_bar::draw_text(
                    canvas,
                    font,
                    &text,
                    right - w,
                    baseline,
                    size,
                    ln_color,
                    255,
                );
            }
            // code text
            let mut pen = code_cell_x;
            let chars: Vec<char> = line.chars().collect();
            for (ci, ch) in chars.iter().enumerate() {
                let advance = font.advance_em(*ch) * size;
                if *ch != ' ' {
                    let scope = self
                        .scopes
                        .get(i)
                        .and_then(|row| row.get(ci))
                        .copied()
                        .unwrap_or(Scope::Plain);
                    let color = theme.color(scope).rgba();
                    if let Some(o) = font.outline(*ch) {
                        if let Some(bmp) =
                            crate::fonts::raster::rasterize(&o, font.upem, size, 0.0, 0.0)
                        {
                            canvas.draw_glyph(
                                &bmp,
                                pen + bmp.left,
                                baseline + bmp.top,
                                (color.0, color.1, color.2, alpha),
                            );
                        }
                    }
                }
                pen += advance;
            }
        }
        let _ = (lang, code, top);
    }
}

pub fn digit_count(n: usize) -> usize {
    if n == 0 {
        1
    } else {
        let mut n = n;
        let mut c = 0;
        while n > 0 {
            c += 1;
            n /= 10;
        }
        c
    }
}
