//! Breadcrumbs showing the path of the snapshot source.
use crate::fonts::Font;
use crate::render::Canvas;
use crate::utils::color::Color;

pub struct Breadcrumbs;

impl Breadcrumbs {
    pub const FONT_SIZE: f32 = 10.4;
    pub const BASELINE_OFFSET: f32 = 10.5;

    pub fn paint(
        canvas: &mut Canvas,
        window_x: f32,
        window_y: f32,
        scale: u32,
        path: &str,
        separator: &str,
        font: &mut Font,
        color: &Color,
    ) {
        if path.is_empty() {
            return;
        }
        let text = if separator == "/" {
            path.to_string()
        } else {
            path.replace('/', separator)
        };
        let s = scale as f32;
        let size = Self::FONT_SIZE * s;
        let baseline = window_y
            + (crate::components::mac_window_bar::MacWindowBar::height() + Self::BASELINE_OFFSET)
                * s;
        crate::components::mac_window_bar::draw_text(
            canvas,
            font,
            &text,
            window_x + 16.0 * s,
            baseline,
            size,
            color.rgba(),
            255,
        );
    }
}
