//! Highlight line helpers.
use crate::utils::color::Color;

/// A highlighted range of lines with a color.
#[derive(Debug, Clone)]
pub struct HighlightRange {
    pub start: usize,
    pub end: usize,
    pub color: Color,
}

/// Parse the `--raw-highlight-lines` JSON payload.
pub fn parse_raw(
    json: &str,
) -> Result<Vec<HighlightRange>, serde_json::Error> {
    #[derive(serde::Deserialize)]
    #[serde(untagged)]
    enum Item {
        Pair(serde_json::Value),
    }
    let _ = Item::deserialize(serde_json::Deserializer::from_str(json))?;
    let value: serde_json::Value = serde_json::from_str(json)?;
    let arr = match value {
        serde_json::Value::Array(a) => a,
        _ => {
            return Err(serde_json::Error::custom(
                "data did not match any variant of untagged enum HighlightLine",
            ))
        }
    };
    let mut out = Vec::new();
    for item in arr {
        let nums: Vec<serde_json::Value> = match item {
            serde_json::Value::Array(a) => a,
            _ => {
                return Err(serde_json::Error::custom(
                    "data did not match any variant of untagged enum HighlightLine",
                ))
            }
        };
        let (start, end, color) = match nums.len() {
            2 => {
                let l = nums[0].as_u64().unwrap_or(0) as usize;
                let c = nums[1].as_str().unwrap_or("#ffffff").to_string();
                (l, l, c)
            }
            3 => {
                let l = nums[0].as_u64().unwrap_or(0) as usize;
                let r = nums[1].as_u64().unwrap_or(0) as usize;
                let c = nums[2].as_str().unwrap_or("#ffffff").to_string();
                (l, r, c)
            }
            _ => {
                return Err(serde_json::Error::custom(
                    "data did not match any variant of untagged enum HighlightLine",
                ))
            }
        };
        out.push(HighlightRange {
            start,
            end,
            color: Color::from_hex(&color),
        });
    }
    Ok(out)
}
