}

/// Render the snapshot into a canvas.
pub fn render_canvas(params: &SnapshotParams) -> Canvas {
    let scale = params.scale_factor as u32;
    let theme = Theme::find(&params.code_theme)
        .unwrap_or_else(|| panic!("Cannot find {} theme", params.code_theme));

    let lines: Vec<String> = params.code.lines().map(|l| l.to_string()).collect();
    let lines = if lines.is_empty() {
        vec![String::new()]
    } else {
        lines
    };
    let lang = params
        .language_id
        .as_deref()
        .and_then(crate::highlight::find_language)
        .or_else(|| {
            params
                .file_path
                .as_deref()
                .and_then(crate::highlight::detect_language)
        });
    let block = CodeBlock::new(lines.clone(), lang, &params.code);

    let container = container::Container::new(&params.window);
    let content_w = block.content_width(params.has_line_numbers, params.start_line);
    let content_h = block.content_height(params.breadcrumbs);
    let (cw, ch) = container.canvas_size(content_w, content_h, scale);
    let mut canvas = Canvas::new(cw, ch);

    let bg = background::ResolvedBackground::new(&params.background, cw as f32, ch as f32);
    let _first = bg.first_color();
    for y in 0..ch {
        for x in 0..cw {
            let c = bg.color_at(x as f32 + 0.5, y as f32 + 0.5);
            canvas.set(x, y, c);
        }
    }

    let geo = container.geometry(content_w, content_h, scale);
    container.paint_shadow(&mut canvas, &geo, scale);
    let bg_color = theme_window_color(&theme);
    container.paint_window(&mut canvas, &geo, bg_color);
    container.paint_border(&mut canvas, &geo, scale);

    if params.window.mac_window_bar {
        let mut title_font = fonts::system::load(
            &params.window.title_config.font_family,
            &["DejaVu Sans", "DejaVu Serif"],
        )
        .unwrap_or_else(|| fallback_font());
        crate::components::mac_window_bar::MacWindowBar::paint(
            &mut canvas,
            geo.x,
            geo.y,
            geo.width,
            scale,
            params.title.as_deref(),
            &mut title_font,
            &Color::from_hex(&params.title_color),
        );
    }

    if params.breadcrumbs {
        if let Some(path) = &params.file_path {
            let mut bfont = fonts::system::load(
                &params.breadcrumbs_font_family,
                &["DejaVu Sans Mono", "DejaVu Sans"],
            )
            .unwrap_or_else(|| fallback_font());
            crate::components::breadcrumbs::Breadcrumbs::paint(
                &mut canvas,
                geo.x,
                geo.y,
                scale,
                path,
                &params.breadcrumbs_separator,
                &mut bfont,
                &Color::from_hex(&params.breadcrumbs_color),
            );
        }
    }

    let mut font = fonts::system::load(&params.code_config.font_family, &["DejaVu Sans Mono", "DejaVu Sans"])
        .unwrap_or_else(|| fallback_font());

    let mut ranges = params.highlight_ranges.clone();
    for l in &params.delete_lines {
        ranges.push((*l, *l, Color::from_hex(&params.delete_line_color)));
    }
    for l in &params.add_lines {
        ranges.push((*l, *l, Color::from_hex(&params.add_line_color)));
    }
    block.paint(
        &mut canvas,
        geo.x,
        geo.y,
        geo.width,
        scale,
        &theme,
        &mut font,
        lang,
        &params.code,
        params.has_line_numbers,
        params.start_line,
        &Color::from_hex(&params.line_number_color),
        &ranges,
    );

    if params.margin_y >= 82.0 && !params.watermark_text.is_empty() {
        let mut wfont = fonts::system::load(
            &params.watermark_font_family,
            &["DejaVu Sans", "DejaVu Serif"],
        )
        .unwrap_or_else(|| fallback_font());
        watermark::Watermark::paint(
            &mut canvas,
            geo.x,
            geo.width,
            geo.y + geo.height,
            scale,
            &params.watermark_text,
            &mut wfont,
            &Color::from_hex(&params.watermark_color),
        );
    }
    canvas
}

fn theme_window_color(_theme: &Theme) -> (u8, u8, u8, u8) {
    // The window background of the candy theme.
    (40, 42, 54, 255)
}

pub fn fallback_font() -> Font {
    let dirs = fonts::system::font_dirs();
    for dir in dirs {
        let mut files = Vec::new();
        fonts::system::walk_public(&dir, &mut files, 0);
        for f in files {
            if let Ok(data) = std::fs::read(&f) {
                if let Some(font) = Font::parse(data, "fallback") {
                    return font;
                }
            }
        }
    }
    Font::parse(Vec::new(), "empty").unwrap_or_else(|| unreachable!())
}
