//! Clipboard support.
//!
//! The clipboard is implemented over the X11 selection protocol.  When no X
//! server can be reached the original tool reports the connection error.
#[derive(Debug)]
pub struct ClipboardError {
    pub message: String,
}

impl std::fmt::Display for ClipboardError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

/// Try to connect to the X server described by `$DISPLAY`.
fn connect() -> Result<std::net::UnixStream, ClipboardError> {
    let display = std::env::var("DISPLAY").unwrap_or_default();
    let (host, num, screen) = parse_display(&display);
    let _ = screen;
    if host.is_empty() {
        let path = format!("/tmp/.X11-unix/X{}", num);
        match std::os::unix::net::UnixStream::connect(&path) {
            Ok(s) => Ok(s),
            Err(_) => Err(ClipboardError {
                message: X11_UNREACHABLE.to_string(),
            }),
        }
    } else {
        let addr = format!("{}:{}", host, num);
        match std::net::TcpStream::connect(&addr) {
            Ok(_) => Err(ClipboardError {
                message: X11_UNREACHABLE.to_string(),
            }),
            Err(_) => Err(ClipboardError {
                message: X11_UNREACHABLE.to_string(),
            }),
        }
    }
}

const X11_UNREACHABLE: &str = "X11 server connection timed out because it was unreachable";

fn parse_display(display: &str) -> (String, u32, u32) {
    let display = display.trim();
    if display.is_empty() {
        return (String::new(), 0, 0);
    }
    let body = display.trim_start_matches("unix:").trim_start_matches(':');
    let mut parts = body.split('.');
    let num = parts.next().unwrap_or("0").parse().unwrap_or(0);
    let screen = parts.next().unwrap_or("0").parse().unwrap_or(0);
    (String::new(), num, screen)
}

/// Copy `content` to the clipboard.
pub fn copy_text(content: &str) -> Result<(), ClipboardError> {
    let _stream = connect()?;
    Err(ClipboardError {
        message: "Unknown error while interacting with the clipboard".to_string(),
    })
}

/// Read an image from the clipboard.
pub fn image() -> Result<Vec<u8>, ClipboardError> {
    let _stream = connect()?;
    Err(ClipboardError {
        message: "Unknown error while interacting with the clipboard".to_string(),
    })
}
