            .value_parser(clap::builder::PossibleValuesParser::new(["ascii", "image"]))
    )
    .arg(Arg::new("config").long("config").value_name("CONFIG"))
}

fn config_paths() -> (PathBuf, PathBuf) {
    let base = match dirs::config_dir() {
        Some(d) => d,
        None => PathBuf::from("."),
    };
    let dir = base.join("codesnap");
    (dir.join("config.json"), dir.join("remote_themes"))
}

/// Read the configuration file, creating a default one when missing.
fn load_config(explicit: Option<&str>) -> (Option<String>, CodeSnapCLIConfig) {
    let (default_path, themes_dir) = config_paths();
    let _ = std::fs::create_dir_all(&default_path.parent().unwrap_or(&default_path));
    let _ = std::fs::create_dir_all(&themes_dir);
    match explicit {
        Some(path) => {
            let content = match std::fs::read_to_string(path) {
                Ok(c) => c,
                Err(e) => error!("{}", e),
            };
            (Some(content), config::default_cli_config())
        }
        None => {
            if !default_path.exists() {
                let default = config::default_cli_config();
                let json = config::to_pretty_json(&default);
                if std::fs::write(&default_path, json).is_ok() {
                    info(&format!(
                        "Automated created config file at {:?}",
                        default_path.display().to_string()
                    ));
                }
                (None, default)
            } else {
                match std::fs::read_to_string(&default_path) {
                    Ok(c) => (Some(c), config::default_cli_config()),
                    Err(e) => error!("{}", e),
                }
            }
        }
    }
}

fn parse_usize_part(part: &str) -> usize {
    match part.parse::<usize>() {
        Ok(v) => v,
        Err(e) => error!("{}", e),
    }
}

/// Convert a highlight range string into start/end indices.
fn range_bounds(range: &str) -> (usize, usize) {
    let parsed = match parse_range(range) {
        Ok(r) => r,
        Err(RangeError::InvalidFormat) => error!("Invalid range format"),
        Err(RangeError::ParseInt(e)) => error!("{}", e),
    };
    let end = parsed.end.unwrap_or(usize::MAX);
    match parsed.start {
        Some(s) => {
            if s <= end {
                (s, end)
            } else {
                (end, s)
            }
        }
        None => (1, end),
    }
}

fn cow(messages: &[&str]) -> String {
    let idx = random_index(messages.len());
    let message = messages[idx];
    let l = message.chars().count();
    let mut out = String::new();
    out.push(' ');
    for _ in 0..l + 2 {
        out.push('_');
    }
    out.push('\n');
    out.push_str(&format!("< {} >\n", message));
    out.push(' ');
    for _ in 0..l + 2 {
        out.push('-');
    }
    out.push('\n');
    out.push_str("        \\\n");
    out.push_str("         \\\n");
    out.push_str("            _~^~^~_\n");
    out.push_str("        \\) /  o o  \\ (/\n");
    out.push_str("          '_   -   _'\n");
    out.push_str("          / '-----' \\\n");
    out
}

fn random_index(n: usize) -> usize {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.subsec_nanos() as u64 ^ (d.as_secs() << 20))
        .unwrap_or(0);
    let pid = std::process::id() as u64;
    (nanos.wrapping_mul(0x5dee_ece6_6d25_6d0d).wrapping_add(pid)) % n.max(1) as u64
        as usize
}

fn main() {
    let matches = build_command().get_matches();

    let silent = matches.get_flag("silent");
    let output = matches.get_one::<String>("output").cloned().unwrap();
    let snapshot_type = matches.get_one::<String>("type").cloned().unwrap();
    let config_path = matches.get_one::<String>("config").cloned();
    let scale_factor = matches
        .get_one::<u8>("scale_factor")
        .copied()
        .unwrap_or(3);

    // 1. read the configuration file
    let (raw_config, _default) = load_config(config_path.as_deref());

    // 2. read the source file
    let mut code: Option<String> = None;
    let mut file_path: Option<String> = None;
    if let Some(path) = matches.get_one::<String>("from_file") {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => error!("{}", e),
        };
        file_path = Some(path.clone());
        code = Some(content);
    }
    if code.is_none() {
        if let Some(v) = matches.get_one::<String>("from_code") {
            code = Some(v.clone());
            file_path = matches.get_one::<String>("file_path").cloned();
        }
    }

    // 3. apply the range to the code we have so far
    let mut lines: Vec<String> = match &code {
        Some(c) => c.lines().map(|l| l.to_string()).collect(),
        None => Vec::new(),
    };
    if let Some(range) = matches.get_one::<String>("range") {
        let parsed = match parse_range(range) {
            Ok(r) => r,
            Err(RangeError::InvalidFormat) => error!("Invalid range format"),
            Err(RangeError::ParseInt(e)) => error!("{}", e),
        };
        lines = core::utils::range::select_lines(&lines, &parsed);
        code = Some(lines.join("\n"));
    }
    let line_count = lines.len().max(1);

    // 4. parse --raw-highlight-lines
    let mut raw_ranges: Vec<(usize, usize, Color)> = Vec::new();
    if let Some(raw) = matches.get_one::<String>("raw_highlight_lines") {
        match core::components::highlight::parse_raw(raw) {
            Ok(r) => {
                for item in r {
                    raw_ranges.push((item.start, item.end, item.color));
                }
            }
            Err(e) => error!("{}", e),
        }
    }

    // 5. validate the highlight ranges built from the simple options
    let mut simple_ranges: Vec<(usize, usize, Color)> = Vec::new();
    if let Some(range) = matches.get_one::<String>("highlight_range") {
        let (start, end) = range_bounds(range);
        let color = matches
            .get_one::<String>("highlight_range_color")
            .cloned()
            .unwrap_or_else(|| "#ffffff10".to_string());
        simple_ranges.push((start, end, Color::from_hex(&color)));
    }
    for value in matches.get_many::<String>("delete_line").unwrap_or_default() {
        let n: usize = value.parse().unwrap_or_else(|e| error!("{}", e));
        simple_ranges.push((n, n, Color::from_hex("#ff6b6b30")));
    }
    for value in matches.get_many::<String>("add_line").unwrap_or_default() {
        let n: usize = value.parse().unwrap_or_else(|e| error!("{}", e));
        simple_ranges.push((n, n, Color::from_hex("#2ecc7130")));
    }
    for (_s, e, _c) in &simple_ranges {
        if *e > line_count {
            error!("The highlight end range should be less than or equal to {}", line_count);
        }
    }

    // 6. validate the scale factor
    if scale_factor <= 1 {
        error!("The scale factor must be greater than 1");
    }

    // 7. parse the configuration
    let parsed: CodeSnapCLIConfig = match &raw_config {
        Some(content) => match config::from_json(content) {
            Ok(c) => c,
            Err(e) => error!("{}", e),
        },
        None => config::default_cli_config(),
    };
    let snapshot_config = &parsed.snapshot_config;
    let background = match &snapshot_config.background {
        Some(b) => b.clone(),
        None => error!("`background` must be initialized"),
    };

    // 8. resolve the theme
    let theme_name = matches
        .get_one::<String>("code_theme")
        .cloned()
        .or_else(|| snapshot_config.theme.clone())
        .unwrap_or_else(|| "candy".to_string());
    if Theme::find(&theme_name).is_none() {
        error!("Cannot find {} theme", theme_name);
    }

    // 9. resolve the remaining inputs
    if code.is_none() {
        if let Some(image) = matches.get_one::<String>("from_image") {
            let data = match image {
                Some(p) => std::fs::read(p).unwrap_or_default(),
                None => {
                    let mut buf = Vec::new();
                    let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
                    buf
                }
            };
            // A valid PNG signature is required.
            if data.len() < 33 {
                error!("Unexpected end of data before image end.");
            }
            if &data[0..8] != b"\x89PNG\r\n\x1a\n" {
                error!("Invalid PNG signature.");
            }
            error!("Invalid PNG signature.");
        }
        if matches.get_flag("from_clipboard") {
            match core::utils::clipboard::image() {
                Ok(_) => {}
                Err(e) => error!(
                    "Unknown error while interacting with the clipboard: {}",
                    e
                ),
            }
        }
        if let Some(values) = matches.get_many::<String>("execute") {
            let command: Vec<String> = values.cloned().collect();
            if !matches.get_flag("skip") {
                let output = std::process::Command::new(&command[0])
                    .args(&command[1..])
                    .output();
                match output {
                    Ok(o) => {
                        code = Some(String::from_utf_lossy(&o.stdout).to_string());
                    }
                    Err(_) => {}
                }
            } else {
                code = Some(command.join(" "));
            }
        }
    }
    if code.is_none() {
        if matches.get_one::<String>("from_code").is_some() {
            let mut buf = Vec::new();
            let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
            code = Some(String::from_utf_lossy(&buf).to_string());
        }
    }
    let code = code.unwrap_or_default();

    // build the parameters
    let mut overrides = Overrides {
        code_font_family: matches.get_one::<String>("code_font_family").cloned(),
        code_theme: Some(theme_name.clone()),
        breadcrumbs: Some(matches.get_one::<String>("has_breadcrumbs").map(|v| v == "true").unwrap_or(false)),
        has_line_numbers: matches.get_flag("has_line_number"),
        breadcrumbs_separator: matches.get_one::<String>("breadcrumbs_separator").cloned(),
        breadcrumbs_color: matches.get_one::<String>("breadcrumbs_color").cloned(),
        breadcrumbs_font_family: matches.get_one::<String>("breadcrumbs_font_family").cloned(),
        start_line: matches
            .get_one::<usize>("start_line_number")
            .copied()
            .unwrap_or(1),
        line_number_color: matches.get_one::<String>("line_number_color").cloned(),
        delete_lines: matches
            .get_many::<String>("delete_line")
            .unwrap_or_default()
            .filter_map(|v| v.parse::<usize>().ok())
            .collect(),
        delete_line_color: matches.get_one::<String>("delete_line_color").cloned(),
        add_lines: matches
            .get_many::<String>("add_line")
            .unwrap_or_default()
            .filter_map(|v| v.parse::<usize>().ok())
            .collect(),
        add_line_color: matches.get_one::<String>("add_line_color").cloned(),
        highlight_range_color: matches.get_one::<String>("highlight_range_color").cloned(),
        watermark: matches.get_one::<String>("watermark").cloned(),
        watermark_font_family: matches.get_one::<String>("watermark_font_family").cloned(),
        watermark_color: matches.get_one::<String>("watermark_color").cloned(),
        shadow_radius: matches.get_one::<f32>("shadow_radius").copied(),
        shadow_color: matches.get_one::<String>("shadow_color").cloned(),
        mac_window_bar: matches
            .get_one::<String>("mac_window_bar")
            .map(|v| v == "true"),
        has_border: matches.get_flag("has_border"),
        border_color: matches.get_one::<String>("border_color").cloned(),
        margin_x: matches.get_one::<f32>("margin_x").copied(),
        margin_y: matches.get_one::<f32>("margin_y").copied(),
        title: matches.get_one::<String>("title").cloned(),
        title_font_family: matches.get_one::<String>("title_font_family").cloned(),
        title_color: matches.get_one::<String>("title_color").cloned(),
        background: matches.get_one::<String>("background").cloned(),
        scale_factor,
    };

    let mut params = SnapshotParams::from_config(snapshot_config, &overrides);
    params.code = code.clone();
    params.file_path = file_path.clone();
    params.language_id = matches.get_one::<String>("language").cloned();
    params.breadcrumbs = *overrides.breadcrumbs.as_ref().unwrap_or(&false);
    params.breadcrumbs_separator = overrides
        .breadcrumbs_separator
        .clone()
        .unwrap_or_else(|| "/".to_string());
    params.breadcrumbs_color = overrides
        .breadcrumbs_color
        .clone()
        .unwrap_or_else(|| "#80848b".to_string());
    params.breadcrumbs_font_family = overrides
        .breadcrumbs_font_family
        .clone()
        .unwrap_or_else(|| params.code_config.font_family.clone());
    params.watermark_text = overrides.watermark.clone().unwrap_or_else(|| {
        snapshot_config
            .watermark
            .as_ref()
            .map(|w| w.content.clone())
            .unwrap_or_default()
    });
    params.watermark_font_family = overrides
        .watermark_font_family
        .clone()
        .unwrap_or_else(|| "Pacifico".to_string());
    params.watermark_color = overrides
        .watermark_color
        .clone()
        .unwrap_or_else(|| "#ffffff".to_string());
    params.highlight_ranges = simple_ranges;
    params.highlight_ranges.extend(raw_ranges);
    params.code_theme = theme_name.clone();
    params.line_number_color = overrides
        .line_number_color
        .clone()
        .unwrap_or_else(|| "#495162".to_string());
    params.delete_line_color = overrides
        .delete_line_color
        .clone()
        .unwrap_or_else(|| "#ff6b6b30".to_string());
    params.add_line_color = overrides
        .add_line_color
        .clone()
        .unwrap_or_else(|| "#2ecc7130".to_string());
    params.highlight_range_color = overrides
        .highlight_range_color
        .clone()
        .unwrap_or_else(|| "#ffffff10".to_string());

    // ascii snapshots can only be copied to the clipboard
    if snapshot_type == "ascii" {
        if output != "clipboard" {
            warn("ASCII snapshot only supports copying to clipboard");
            std::process::exit(0);
        }
        match core::utils::clipboard::copy_text(&params.code) {
            Ok(()) => success("Snapshot copied to clipboard successful!"),
            Err(e) => error!(
                "Unknown error while interacting with the clipboard: {}",
                e
            ),
        }
        if parsed.print_eggs {
            print!("{}", cow(&config::EGG_MESSAGES));
        }
        return;
    }

    // Determine the output format from the file extension.
    if output == "clipboard" {
        let bytes = core::snapshot::render_png(&params);
        let text = format!(
            "<img src=\"data:image/png;base64,{}\" />",
            base64_encode(&bytes)
        );
        match core::utils::clipboard::copy_text(&text) {
            Ok(()) => {
                if !silent {
                    success("Snapshot copied to clipboard successful!");
                }
            }
            Err(e) => error!(
                "Unknown error while interacting with the clipboard: {}",
                e
            ),
        }
        if parsed.print_eggs {
            print!("{}", cow(&config::EGG_MESSAGES));
        }
        return;
    }

    let ext = output
        .rsplit('.')
        .next()
        .unwrap_or("");
    let bytes = core::snapshot::render_png(&params);
    let content: String = match ext {
        "png" => String::from_utf_lossy(&bytes).to_string(),
        "svg" => format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>",
            base64_encode(&bytes)
        ),
        "html" => format!(
            "<img src=\"data:image/png;base64,{}\" />",
            base64_encode(&bytes)
        ),
        _ => error!("Unsupported output format"),
    };
    if let Err(e) = std::fs::write(&output, content.as_bytes()) {
        error!("{}", e);
    }
    if !silent {
        success(&format!("Snapshot saved to {} successful!", output));
    }
    if parsed.print_eggs {
        print!("{}", cow(&config::EGG_MESSAGES));
    }
    let _ = &mut overrides;
}

fn base64_encode(data: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(TABLE[(n >> 18) as usize & 63] as char);
        out.push(TABLE[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 {
            TABLE[(n >> 6) as usize & 63] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            TABLE[n as usize & 63] as char
        } else {
            '='
        });
    }
    out
}
