new='''    // 2. resolve the input source; `--execute` has the highest precedence and
    //    is handled after the other validations.
    let pending_execute = matches.contains_id("execute");
    let mut code: Option<String> = None;
    let mut file_path: Option<String> = None;
    let mut image_size: Option<(u32, u32)> = None;
    if !pending_execute {
        if matches.contains_id("from_image") {
            let mut buf: Vec<u8> = Vec::new();
            match matches.get_one::<String>("from_image") {
                Some(value) => buf = value.as_bytes().to_vec(),
                None => {
                    let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
                }
            }
            match core::snapshot::png_dimensions(&buf) {
                Ok(dims) => image_size = Some(dims),
                Err(e) => bail!("{}", e),
            }
        } else if let Some(path) = matches.get_one::<String>("from_file") {
            let content = match std::fs::read_to_string(path) {
                Ok(c) => c,
                Err(e) => bail!("{}", e),
            };
            file_path = Some(path.clone());
            code = Some(content);
        } else if let Some(value) = matches.get_one::<String>("from_code") {
            code = Some(value.clone());
            file_path = matches.get_one::<String>("file_path").cloned();
        } else if matches.contains_id("from_code") {
            let mut buf = Vec::new();
            let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
            code = Some(String::from_utf8_lossy(&buf).to_string());
            file_path = matches.get_one::<String>("file_path").cloned();
        }
    }

    // 3. apply the requested range
    if let Some(range) = matches.get_one::<String>("range") {
        let parsed = match parse_range(range) {
            Ok(r) => r,
            Err(RangeError::InvalidFormat) => bail!("Invalid range format"),
            Err(RangeError::ParseInt(e)) => bail!("{}", e),
        };
        let lines: Vec<String> = match &code {
            Some(c) => c.lines().map(|l| l.to_string()).collect(),
            None => Vec::new(),
        };
        let selected = core::utils::range::select_lines(&lines, &parsed);
        code = Some(selected.join("\\n"));
    }
    let line_count = code
        .as_deref()
        .map(|c| c.lines().count())
        .unwrap_or(1)
        .max(1);

    // 4. parse --raw-highlight-lines
    let mut raw_ranges: Vec<(usize, usize, Color)> = Vec::new();
    if let Some(raw) = matches.get_one::<String>("raw_highlight_lines") {
        match core::components::highlight::parse_raw(raw) {
            Ok(r) => {
                for item in r {
                    raw_ranges.push((item.start, item.end, item.color));
                }
            }
            Err(e) => bail!("{}", e),
        }
    }

    // 5. validate the highlight ranges built from the simple options
    let mut simple_ranges: Vec<(usize, usize, Color)> = Vec::new();
    if let Some(range) = matches.get_one::<String>("highlight_range") {
        let (start, end) = range_bounds(range);
        let color = matches
            .get_one::<String>("highlight_range_color")
            .cloned()
            .unwrap_or_else(|| "#ffffff10".to_string());
        simple_ranges.push((start, end, Color::from_hex(&color)));
    }
    for value in matches.get_many::<String>("delete_line").unwrap_or_default() {
        let n: usize = value.parse().unwrap_or_else(|e| bail!("{}", e));
        simple_ranges.push((n, n, Color::from_hex("#ff6b6b30")));
    }
    for value in matches.get_many::<String>("add_line").unwrap_or_default() {
        let n: usize = value.parse().unwrap_or_else(|e| bail!("{}", e));
        simple_ranges.push((n, n, Color::from_hex("#2ecc7130")));
    }
    for (_s, e, _c) in &simple_ranges {
        if *e > line_count {
            bail!(
                "The highlight end range should be less than or equal to {}",
                line_count
            );
        }
    }

    // 6. the clipboard is read after the highlight validation
    if code.is_none() && !pending_execute && matches.get_flag("from_clipboard") {
        match core::utils::clipboard::image() {
            Ok(_) => {}
            Err(e) => bail!("Unknown error while interacting with the clipboard: {}", e),
        }
    }

    // 7. validate the scale factor
    if scale_factor <= 1 {
        bail!("The scale factor must be greater than 1");
    }

    // 8. parse the configuration
    let parsed: CodeSnapCLIConfig = match &raw_config {
        Some(content) => match config::from_json(content) {
            Ok(c) => c,
            Err(e) => bail!("{}", e),
        },
        None => config::default_cli_config(),
    };
    let snapshot_config = &parsed.snapshot_config;
    let background = match &snapshot_config.background {
        Some(b) => b.clone(),
        None => bail!("`background` must be initialized"),
    };

    // 9. resolve the theme
    let theme_name = matches
        .get_one::<String>("code_theme")
        .cloned()
        .or_else(|| snapshot_config.theme.clone())
        .unwrap_or_else(|| "candy".to_string());
    if Theme::find(&theme_name).is_none() {
        bail!("Cannot find {} theme", theme_name);
    }

    // 10. execute the command when requested
    if pending_execute {
        let command: Vec<String> = matches
            .get_many::<String>("execute")
            .unwrap_or_default()
            .cloned()
            .collect();
        if matches.get_flag("skip") {
            code = Some(format!("> {}", command.join(" ")));
        } else {
            let out = std::process::Command::new(&command[0]).args(&command[1..]).output();
            match out {
                Ok(o) => code = Some(String::from_utf8_lossy(&o.stdout).to_string()),
                Err(_) => code = Some(String::new()),
            }
        }
        file_path = matches.get_one::<String>("file_path").cloned();
    }

'''
