new='''pub fn png_dimensions(data: &[u8]) -> Result<(u32, u32), &'static str> {
    const EOF: &str = "Unexpected end of data before image end.";
    const SIG: &str = "Invalid PNG signature.";
    if data.len() < 4 {
        return Err(EOF);
    }
    if &data[0..4] != b"\\x89PNG" {
        return Err(SIG);
    }
    let mut i = 8usize;
    let mut dims: Option<(u32, u32)> = None;
    let mut first = true;
    while i + 8 <= data.len() {
        let len = u32::from_be_bytes([data[i], data[i + 1], data[i + 2], data[i + 3]]) as usize;
        let kind = &data[i + 4..i + 8];
        if first {
            if kind != b"IHDR" {
                return Err(SIG);
            }
            if i + 8 + 13 > data.len() {
                return Err(EOF);
            }
            let w = u32::from_be_bytes([data[i + 8], data[i + 9], data[i + 10], data[i + 11]]);
            let h = u32::from_be_bytes([
                data[i + 12],
                data[i + 13],
                data[i + 14],
                data[i + 15],
            ]);
            dims = Some((w, h));
            first = false;
        }
        if kind == b"IEND" {
            return match dims {
                Some(d) => Ok(d),
                None => Err(EOF),
            };
        }
        i += 12 + len;
    }
    Err(EOF)
}

