    return t.replace(home,'HOME')
def run(binary, args, home, workdir, stdin=b''):
    os.makedirs(workdir, exist_ok=True)
    env=dict(os.environ); env['HOME']=home
    r=subprocess.run([binary]+args, cwd=workdir, input=stdin, capture_output=True, env=env, timeout=40)
    return r
def files(d):
    out=[]
    for root,ds,fs in os.walk(d):
        ds[:]=[x for x in ds if x not in ('hA','hB')]
        for f in fs:
            out.append(os.path.relpath(os.path.join(root,f), d))
    return sorted(out)
def cmp_case(desc, args, stdin=b''):
    global total, fails
    total+=1
    for d in ['/tmp/cA','/tmp/cB','/tmp/hA','/tmp/hB']:
        shutil.rmtree(d, ignore_errors=True)
        os.makedirs(d, exist_ok=True)
    ra=run(ORIG,args,'/tmp/hA','/tmp/cA',stdin)
    rb=run(MINE,args,'/tmp/hB','/tmp/cB',stdin)
    problems=[]
    if ra.returncode!=rb.returncode: problems.append('rc %s vs %s'%(ra.returncode,rb.returncode))
    oa=norm(ra.stdout.decode('utf-8','replace'),'/tmp/hA'); ob=norm(rb.stdout.decode('utf-8','replace'),'/tmp/hB')
    if oa!=ob: problems.append('stdout:\n  A=%r\n  B=%r'%(oa[:400],ob[:400]))
    ea=norm(ra.stderr.decode('utf-8','replace'),'/tmp/hA'); eb=norm(rb.stderr.decode('utf-8','replace'),'/tmp/hB')
    if ea!=eb:
        import re
        ea2=re.sub(r"\(\d+\)","(PID)",ea); eb2=re.sub(r"\(\d+\)","(PID)",eb)
        if ea2!=eb2: problems.append('stderr:\n  A=%r\n  B=%r'%(ea[:300],eb[:300]))
    fa=files('/tmp/cA'); fb=files('/tmp/cB')
    if fa!=fb: problems.append('files A=%s B=%s'%(fa,fb))
    else:
        for f in fa:
            a=open(os.path.join('/tmp/cA',f),'rb').read(); b=open(os.path.join('/tmp/cB',f),'rb').read()
            if f.endswith('.png') or f.endswith('.svg') or f.endswith('.html'):
                import struct
                def info(data):
                    if data[:8]==b'\x89PNG\r\n\x1a\n':
                        w,h=struct.unpack('>II',data[16:24]); return 'PNG %dx%d len=%d'%(w,h,len(data))
                    return 'len=%d %s'%(len(data), data[:40])
                if info(a)!=info(b): problems.append('%s: %s vs %s'%(f,info(a),info(b)))
            elif a!=b: problems.append('%s differs'%f)
    if problems:
        fails.append((desc,args,problems))
    return problems
def report():
    print('=== %d failures out of %d'%(len(fails),total))
    for desc,args,p in fails:
        print('--- %s  args=%s'%(desc,args))
        for x in p: print('   ',x)
